export default "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no\"><style>:root{color-scheme:light;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom)}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%}[hidden]{display:none!important}</style></head><body><title>Caisse du Bar</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap\">\n<style>\n/* Layout: one-screen phone app, top bar + scrolling view + fixed bottom tab bar; amber \"bottle label\" accent on warm ink neutrals */\n:root{\n  --bg:#f6f3ee; --surface:#fffdf9; --surface2:#efe9df; --line:#ddd3c4;\n  --fg:#231c14; --muted:#75685a; --accent:#c8780a; --accent-ink:#ffffff; --accent-soft:#f6e4c4;\n  --good:#2f7d4f; --good-soft:#dcefe2; --bad:#b3352a; --bad-soft:#f6dcd8; --warn:#9a6a00; --warn-soft:#f7ecc9;\n  --paper:#ffffff; --paper-ink:#1d1d1d;\n  --f-display:\"Bricolage Grotesque\", \"Figtree\", system-ui, sans-serif;\n  --f-body:\"Figtree\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  --f-mono:\"JetBrains Mono\", ui-monospace, Menlo, Consolas, monospace;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){\n  --bg:#17130f; --surface:#211b16; --surface2:#2b241d; --line:#3d3329;\n  --fg:#f3ece2; --muted:#a8998a; --accent:#f0a030; --accent-ink:#1d1406; --accent-soft:#4a3414;\n  --good:#6cc48d; --good-soft:#1e3a29; --bad:#f0897d; --bad-soft:#4a221e; --warn:#e8c25a; --warn-soft:#3d3214;\n  --paper:#fbfaf7; --paper-ink:#1d1d1d; color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#17130f; --surface:#211b16; --surface2:#2b241d; --line:#3d3329;\n  --fg:#f3ece2; --muted:#a8998a; --accent:#f0a030; --accent-ink:#1d1406; --accent-soft:#4a3414;\n  --good:#6cc48d; --good-soft:#1e3a29; --bad:#f0897d; --bad-soft:#4a221e; --warn:#e8c25a; --warn-soft:#3d3214;\n  --paper:#fbfaf7; --paper-ink:#1d1d1d; color-scheme:dark}\nhtml,body{height:100%}\nbody{background:var(--bg);color:var(--fg);font-family:var(--f-body);font-size:15px;line-height:1.4;-webkit-tap-highlight-color:transparent}\n*{box-sizing:border-box}\nbutton{font:inherit;color:inherit;cursor:pointer}\ninput,select{font:inherit;color:var(--fg);background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 12px;width:100%}\ninput:focus-visible,select:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.num{font-variant-numeric:tabular-nums}\n.app{display:flex;flex-direction:column;height:100%;max-width:760px;margin:0 auto}\nheader.top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px 8px}\n.brand{font-family:var(--f-display);font-weight:800;font-size:22px;letter-spacing:-.01em;margin:0;text-wrap:balance}\n.sync{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px;white-space:nowrap}\n.role{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:5px 10px;font-size:12px;font-weight:700;display:flex;align-items:center;gap:5px}\n.role.admin{background:var(--accent-soft);border-color:var(--accent);color:var(--fg)}\n.hd-right{display:flex;flex-direction:column;align-items:flex-end;gap:4px}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--muted)}\n.dot.ok{background:var(--good)} .dot.off{background:var(--warn)}\nmain{flex:1;overflow-y:auto;padding:4px 16px 16px;min-height:0}\nnav.tabs{display:grid;grid-template-columns:repeat(6,1fr);border-top:1px solid var(--line);background:var(--surface);padding-bottom:env(safe-area-inset-bottom,0px)}\nnav.tabs button{background:none;border:0;padding:8px 0 10px;font-size:11px;min-width:0;font-weight:600;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:3px}\nnav.tabs button svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\nnav.tabs button[aria-current=\"true\"]{color:var(--accent)}\n.badge-n{background:var(--accent);color:var(--accent-ink);border-radius:9px;font-size:10px;padding:0 5px;margin-left:2px}\nh2{font-family:var(--f-display);font-weight:800;font-size:20px;margin:8px 0 10px;text-wrap:balance}\nh3{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:18px 0 8px;font-weight:700}\n.chips{display:flex;gap:8px;overflow-x:auto;padding:4px 0 10px;scrollbar-width:none}\n.chip{flex:none;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:7px 14px;font-weight:600;font-size:14px}\n.chip[aria-pressed=\"true\"]{background:var(--fg);color:var(--bg);border-color:var(--fg)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}\n.prod{position:relative;text-align:left;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 12px 10px;display:flex;flex-direction:column;gap:4px;min-height:96px}\n.prod:active{transform:scale(.97)}\n.prod .nm{font-weight:700;font-size:15px;line-height:1.2}\n.prod .pr{margin-top:auto;font-family:var(--f-display);font-weight:800;font-size:18px}\n.prod .eu{font-size:12px;color:var(--muted)}\n.prod .st{position:absolute;top:8px;right:8px;font-size:11px;font-weight:700;border-radius:6px;padding:1px 6px;background:var(--surface2);color:var(--muted)}\n.prod .st.low{background:var(--warn-soft);color:var(--warn)} .prod .st.out{background:var(--bad-soft);color:var(--bad)}\n.prod .qty{position:absolute;top:-6px;left:-6px;background:var(--accent);color:var(--accent-ink);font-weight:800;border-radius:999px;min-width:24px;height:24px;display:grid;place-items:center;font-size:13px;padding:0 6px}\n.cartbar{position:sticky;bottom:0;margin:12px -16px -16px;padding:10px 16px;background:var(--surface);border-top:1px solid var(--line);display:flex;align-items:center;gap:10px}\n.cartbar .tot{flex:1;min-width:0}\n.cartbar .tot b{font-family:var(--f-display);font-size:22px;display:block}\n.cartbar .tot span{font-size:12px;color:var(--muted)}\n.btn{border:0;border-radius:12px;padding:12px 16px;font-weight:700;background:var(--surface2);color:var(--fg)}\n.btn.pri{background:var(--accent);color:var(--accent-ink)}\n.btn.danger{background:var(--bad-soft);color:var(--bad)}\n.btn.ghost{background:none;border:1px solid var(--line)}\n.btn.sm{padding:7px 11px;font-size:13px;border-radius:9px}\n.btn.wide{width:100%}\n.btn:disabled{opacity:.45}\n.row{display:flex;gap:10px;align-items:center}\n.row.wrap{flex-wrap:wrap}\n.list{background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}\n.li{display:flex;align-items:center;gap:10px;padding:11px 14px;border-top:1px solid var(--line)}\n.li:first-child{border-top:0}\n.li .main{flex:1;min-width:0}\n.li .main b{display:block;font-weight:600}\n.li .main small{color:var(--muted)}\n.li .right{text-align:right;white-space:nowrap}\nbutton.li{width:100%;background:none;border:0;border-top:1px solid var(--line);text-align:left}\nbutton.li:first-child{border-top:0}\n.pill{font-size:11px;font-weight:700;border-radius:6px;padding:2px 7px;white-space:nowrap}\n.pill.ok{background:var(--good-soft);color:var(--good)} .pill.low{background:var(--warn-soft);color:var(--warn)} .pill.out{background:var(--bad-soft);color:var(--bad)}\n.stepper{display:flex;align-items:center;gap:6px}\n.stepper button{width:32px;height:32px;border-radius:9px;border:1px solid var(--line);background:var(--surface2);font-weight:800;font-size:17px;line-height:1}\n.kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 14px}\n.kpi.big{grid-column:1/-1;background:var(--fg);color:var(--bg);border-color:var(--fg)}\n.kpi .l{font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}\n.kpi.big .l{color:inherit;opacity:.7}\n.kpi .v{font-family:var(--f-display);font-weight:800;font-size:22px;margin-top:2px}\n.kpi.big .v{font-size:32px}\n.kpi .s{font-size:12px;color:var(--muted)}\n.kpi.big .s{color:inherit;opacity:.75}\n.kpi .v.neg{color:var(--bad)} .kpi .v.pos{color:var(--good)}\n.seg{display:grid;grid-template-columns:repeat(3,1fr);background:var(--surface2);border-radius:12px;padding:3px;gap:3px}\n.seg button{border:0;background:none;border-radius:9px;padding:8px;font-weight:700;color:var(--muted)}\n.seg button[aria-pressed=\"true\"]{background:var(--surface);color:var(--fg);box-shadow:0 1px 2px rgba(0,0,0,.12)}\n.period{display:flex;align-items:center;justify-content:space-between;margin:12px 0}\n.period b{font-family:var(--f-display);font-size:17px;text-align:center;flex:1}\n.chart{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 10px 6px;margin-top:10px}\n.chart svg{display:block;width:100%;height:auto}\n.empty{padding:28px 16px;text-align:center;color:var(--muted)}\n.note{font-size:13px;color:var(--muted);background:var(--surface2);border-radius:12px;padding:10px 12px;margin:10px 0}\n.svc{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}\n.svcrow{display:flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:6px 6px 6px 12px;font-size:14px}\n.svcrow .main{flex:1;min-width:0}\n.svc>.btn{align-self:flex-start}\n.note.warn{background:var(--warn-soft);color:var(--warn)}\nlabel.f{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:600;color:var(--muted)}\n.form{display:grid;gap:12px}\n.form .two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n/* modal */\n.scrim{position:fixed;inset:0;background:rgba(10,8,5,.55);display:flex;align-items:flex-end;justify-content:center;z-index:20}\n.sheet{background:var(--bg);width:100%;max-width:560px;max-height:92%;overflow-y:auto;border-radius:20px 20px 0 0;padding:16px 16px calc(18px + env(safe-area-inset-bottom,0px))}\n.sheet h2{margin-top:0}\n.sheet .close{float:right;background:var(--surface2);border:0;border-radius:999px;width:34px;height:34px;font-size:18px}\n/* receipt */\n.receipt{background:var(--paper);color:var(--paper-ink);font-family:var(--f-mono);font-size:13px;padding:18px 16px 22px;margin:4px auto 14px;max-width:320px;border-radius:4px;box-shadow:0 2px 10px rgba(0,0,0,.18);\n  -webkit-mask:radial-gradient(circle 6px at 50% 100%,transparent 98%,#000) 0 0/14px 100% repeat-x;mask:radial-gradient(circle 6px at 50% 100%,transparent 98%,#000) 0 0/14px 100% repeat-x;padding-bottom:26px}\n.receipt .c{text-align:center}\n.receipt .t{font-weight:600;font-size:16px;letter-spacing:.05em}\n.receipt hr{border:0;border-top:1px dashed #999;margin:8px 0}\n.receipt .r{display:flex;justify-content:space-between;gap:8px}\n.receipt .r span:first-child{min-width:0}.receipt .r span:last-child{white-space:nowrap}\n.receipt .tt{font-weight:600;font-size:15px}\n.toast{position:fixed;left:50%;bottom:calc(84px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--fg);color:var(--bg);padding:10px 16px;border-radius:12px;font-weight:600;z-index:30;max-width:90%;text-align:center}\n.cash{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}.prod:active{transform:none}}\n</style>\n\n<div class=\"app\">\n  <header class=\"top\">\n    <h1 class=\"brand\" id=\"brand\">Caisse du Bar</h1>\n    <div class=\"hd-right\"><button class=\"role\" id=\"rolebtn\" data-act=\"role\">Serveur</button>\n    <div class=\"sync\" id=\"sync\"><span class=\"dot\"></span><span>Chargement…</span></div></div>\n  </header>\n  <main id=\"view\"></main>\n  <nav class=\"tabs\" id=\"tabs\">\n    <button data-tab=\"caisse\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"7\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M7 7V4h10v3M7 12h4M7 16h10\"/></svg>Caisse</button>\n    <button data-tab=\"tables\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 9h16M6 9v10M18 9v10M8 5h8\"/></svg><span>Tables<span id=\"tabcount\"></span></span></button>\n    <button data-tab=\"stock\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 3h6v4l2 3v10a1 1 0 0 1-1 1H8a1 1 0 0 1-1-1V10l2-3z\"/><path d=\"M7 14h10\"/></svg>Stock</button>\n    <button data-tab=\"chiffres\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 20V10M10 20V4M16 20v-7M22 20H2\"/></svg>Chiffres</button>\n    <button data-tab=\"loc\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 11l9-7 9 7\"/><path d=\"M5 10v10h14V10\"/><path d=\"M10 20v-5h4v5\"/></svg>Locations</button>\n    <button data-tab=\"plus\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1 7 17M17 7l2.1-2.1\"/></svg>Réglages</button>\n  </nav>\n</div>\n<div id=\"modal\" hidden></div>\n<div id=\"toast\" class=\"toast\" hidden></div>\n\n<script>\n\"use strict\";\nconst RATE = 655.957; // 1 € = 655,957 FCFA (parité fixe)\nconst LS_KEY = \"caisse-bar.v1\";\nconst COLLS = [\"products\",\"tickets\",\"tabs\",\"moves\",\"charges\",\"settings\",\"apparts\",\"locations\",\"shifts\"];\nconst CATS = [\"Bières\",\"Boosters & mix\",\"Jus\",\"Alcools\",\"Vins\"];\n\n// Carte du bar fournie par le gérant (prix de vente en FCFA). Utilisée par le bouton \"Installer la carte\".\nconst CARTE = [\n  [\"Grande Régab\",\"Bières\",700],[\"Petite Régab\",\"Bières\",500],[\"33 Export\",\"Bières\",700],[\"Beaufort\",\"Bières\",700],\n  [\"Sombreros\",\"Bières\",700],[\"Doppel\",\"Bières\",700],[\"Guinness\",\"Bières\",1000],[\"Moyenne Heineken\",\"Bières\",1300],\n  [\"Petite Heineken\",\"Bières\",1500],[\"Desperados\",\"Bières\",2000],[\"Régab en canette\",\"Bières\",1300],\n  [\"Grande Royal Dutch\",\"Bières\",1500],[\"Petite Royal Dutch\",\"Bières\",1000],[\"Bavaria\",\"Bières\",1200],\n  [\"Booster Zombie\",\"Boosters & mix\",800],[\"Booster Tropical\",\"Boosters & mix\",800],[\"Booster Whisky cola\",\"Boosters & mix\",800],\n  [\"Booster Gin Tonic\",\"Boosters & mix\",800],[\"Booster Gingembre\",\"Boosters & mix\",800],[\"XXL\",\"Boosters & mix\",800],\n  [\"Smirnoff\",\"Boosters & mix\",2000],[\"Vino cola\",\"Boosters & mix\",1000],\n  [\"Grand jus\",\"Jus\",700],[\"Canette de jus\",\"Jus\",800],\n  [\"Liqueur (dose)\",\"Alcools\",2000,3000],[\"Vodka (dose)\",\"Alcools\",2000],[\"Vin (bouteille)\",\"Vins\",5000,10000]\n];\n\n/* ---------- application téléphone (impression Bluetooth) ---------- */\nconst NATIVE = !!window.ReactNativeWebView;\nconst native = msg => { try{ window.ReactNativeWebView.postMessage(JSON.stringify(msg)); }catch(e){} };\nfunction getPrinter(){ try{ return JSON.parse(localStorage.getItem(\"caisse-bar.printer\")||\"null\"); }catch(e){ return null; } }\nfunction setPrinter(p){ try{ localStorage.setItem(\"caisse-bar.printer\", JSON.stringify(p)); }catch(e){} }\nwindow.__fromNative = msg => {\n  if(msg.type===\"printers\"){\n    if(!msg.devices.length){ openModal(`<h2>Imprimante</h2><p>Aucune imprimante appairée. Allumez l'imprimante, ouvrez les réglages Bluetooth du téléphone et appairez-la (code souvent 0000 ou 1234), puis revenez ici.</p>`); return; }\n    openModal(`<h2>Choisir l'imprimante</h2><div class=\"list\">${msg.devices.map(d=>`<button class=\"li\" data-printer=\"${esc(d.address)}\" data-pname=\"${esc(d.name)}\"><div class=\"main\"><b>${esc(d.name||\"Sans nom\")}</b><small>${esc(d.address)}</small></div></button>`).join(\"\")}</div>`);\n  }\n  else if(msg.type===\"printed\"){ toast(\"Ticket imprimé.\"); }\n  else if(msg.type===\"error\"){ toast(msg.message || \"Impression impossible.\"); }\n};\nfunction printTicket(t){\n  const p = getPrinter();\n  if(!p){ toast(\"Choisissez d'abord l'imprimante.\"); native({type:\"listPrinters\"}); return; }\n  const d = new Date(t.ts);\n  native({type:\"print\", address:p.address, ticket:{\n    bar: barName(), no: t.no, date: `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()}`, time: fmtTime(t.ts),\n    table: t.table||\"\", client: t.client||\"\", items: t.items.map(l=>({qty:l.qty, name:l.name, amount:fcfa(l.price*l.qty)})),\n    subtotal: t.discount ? fcfa(t.subtotal) : \"\", discount: t.discount ? \"-\" + fcfa(t.discount) : \"\", total: fcfa(t.total), totalEur: eur(t.total).replace(\"€\",\"EUR\"), pay: t.pay, received: fcfa(t.received), change: t.pay===\"Espèces\" ? fcfa(t.change) : \"\",\n    cancelled: !!t.cancelled, footer: (S.settings.main||{}).footer || \"Merci de votre visite !\"}});\n  toast(\"Impression en cours…\");\n}\n\n/* ---------- utilitaires ---------- */\nconst $ = s => document.querySelector(s);\nconst esc = s => String(s ?? \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst fcfa = n => Math.round(n||0).toLocaleString(\"fr-FR\").replace(/ | /g,\" \") + \" F\";\nconst eur = n => ((n||0)/RATE).toLocaleString(\"fr-FR\",{minimumFractionDigits:2,maximumFractionDigits:2}) + \" €\";\nconst pad = n => String(n).padStart(2,\"0\");\nconst dayKey = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;\nconst parseDay = k => { const [y,m,d] = k.split(\"-\").map(Number); return new Date(y,m-1,d); };\nconst addDays = (d,n) => { const x = new Date(d); x.setDate(x.getDate()+n); return x; };\nconst uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2,8);\nconst MOIS = [\"janvier\",\"février\",\"mars\",\"avril\",\"mai\",\"juin\",\"juillet\",\"août\",\"septembre\",\"octobre\",\"novembre\",\"décembre\"];\nconst JOURS = [\"dim.\",\"lun.\",\"mar.\",\"mer.\",\"jeu.\",\"ven.\",\"sam.\"];\nconst fmtDay = d => `${JOURS[d.getDay()]} ${d.getDate()} ${MOIS[d.getMonth()]}`;\nconst fmtTime = ts => { const d = new Date(ts); return `${pad(d.getHours())}:${pad(d.getMinutes())}`; };\nfunction toast(msg){ const t=$(\"#toast\"); t.textContent=msg; t.hidden=false; clearTimeout(toast._t); toast._t=setTimeout(()=>t.hidden=true,2200); }\n\n/* ---------- rôles : administrateur, gérante (prix d'achat, réductions, annulations), serveur ---------- */\nconst hashPin = pin => { let h = 5381; const x = \"caisse-bar:\" + pin; for(let i=0;i<x.length;i++) h = ((h*33) ^ x.charCodeAt(i)) >>> 0; return h.toString(16); };\nlet role = null; // fixé au démarrage\nconst DEFAULT_ADMIN_PIN = \"\"; // empreinte du code de départ, injectée à la construction (secret ADMIN_PIN_HASH) ; vide = à créer au premier lancement\nconst pins = () => { const m = S.settings.main || {}; return m.adminPin ? m : {...m, adminPin: DEFAULT_ADMIN_PIN}; };\nconst hasAdminPin = () => !!pins().adminPin;\nconst canAdmin = () => role === \"admin\";\nconst canCost = () => role === \"admin\" || role === \"gest\";\nconst ROLE_NAMES = {admin:\"Administrateur\", gest:\"Gérante\", staff:\"Serveur\"};\nlet unlocked = false; // vrai seulement après un code correct\nfunction initRole(){ if(!unlocked) role = hasAdminPin() ? \"staff\" : \"admin\"; }\nfunction lock(){ if(hasAdminPin() && role !== \"staff\"){ role = \"staff\"; unlocked = false; if(tab===\"chiffres\" || tab===\"plus\") tab = \"caisse\"; closeModal(); render(); toast(\"Application verrouillée.\"); } }\nfunction showPin(){\n  openModal(`<h2>Entrer un code</h2><p style=\"color:var(--muted)\">Code administrateur ou code gérante.</p>\n  <div class=\"form\"><input id=\"pin\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Code\">\n  <button class=\"btn pri\" data-act=\"unlock\">Déverrouiller</button></div>`, {kind:\"pin\"});\n  setTimeout(()=>{ const i=$(\"#pin\"); if(i) i.focus(); }, 50);\n}\nlet idleT;\nfunction bumpIdle(){ clearTimeout(idleT); idleT = setTimeout(lock, 10*60*1000); }\n\n/* ---------- données : cache local + base partagée ---------- */\nconst S = { products:{}, tickets:{}, tabs:{}, moves:{}, charges:{}, settings:{}, apparts:{}, locations:{}, shifts:{} };\nlet queue = [];            // écritures en attente (hors ligne)\nlet db = null, online = false, loaded = false;\n\nfunction loadLocal(){\n  try{\n    const raw = localStorage.getItem(LS_KEY); if(!raw) return;\n    const o = JSON.parse(raw);\n    COLLS.forEach(c => { if(o[c]) S[c] = o[c]; });\n    queue = o.queue || [];\n  }catch(e){}\n}\nlet saveT;\nfunction saveLocal(){\n  clearTimeout(saveT);\n  saveT = setTimeout(()=>{ try{ localStorage.setItem(LS_KEY, JSON.stringify({...S, queue})); }catch(e){} }, 150);\n}\nfunction saveNow(){ clearTimeout(saveT); try{ localStorage.setItem(LS_KEY, JSON.stringify({...S, queue})); }catch(e){} }\nwindow.addEventListener(\"pagehide\", saveNow);\ndocument.addEventListener(\"visibilitychange\", ()=>{ if(document.hidden) saveNow(); });\nfunction applyLocal(op){\n  const c = S[op.coll];\n  if(op.op === \"delete\") delete c[op.id];\n  else if(op.op === \"set\") c[op.id] = op.data;\n  else c[op.id] = {...(c[op.id]||{}), ...op.data};\n}\nasync function push(op){\n  const ref = db.doc(op.coll + \"/\" + op.id);\n  if(op.op === \"delete\") return ref.delete();\n  if(op.op === \"set\") return ref.set(op.data);\n  try{ return await ref.update(op.data); }\n  catch(e){ if(e && e.code === \"invalid_argument\" && S[op.coll][op.id]) return ref.set(S[op.coll][op.id]); throw e; }\n}\nlet flushing = false;\nasync function flush(){\n  if(!db || flushing || !queue.length) { setSync(); return; }\n  flushing = true;\n  while(queue.length){\n    try{ await push(queue[0]); queue.shift(); saveLocal(); }\n    catch(e){\n      if(e && (e.code === \"invalid_argument\" || e.code === \"transform_error\")){ queue.shift(); saveLocal(); continue; }\n      online = false; break;\n    }\n  }\n  flushing = false; setSync();\n}\nfunction write(op, coll, id, data){\n  const o = {op, coll, id, data: data ? JSON.parse(JSON.stringify(data)) : undefined};\n  applyLocal(o); if(db) queue.push(o); saveLocal(); flush();\n  syncEnqueue(coll, id, op === \"delete\");\n}\n/* ---------- synchronisation entre téléphones (Supabase), hors artifact ---------- */\nconst SYNC_URL = \"https://mtjieniwbkzkefzjmrkb.supabase.co\", SYNC_ANON = \"sb_publishable_e3F-vC5nbgNz-6-nMuejWA_YwtjuaCp\"; // injectés à la construction (build-html.js) ; vides = synchronisation indisponible\nconst SYNC_LS = \"caisse-bar.sync\", SYNCQ_LS = \"caisse-bar.syncq\", SYNCLAST_LS = \"caisse-bar.synclast\";\nconst lsGet = (k, d) => { try{ const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; }catch(e){ return d; } };\nconst lsSet = (k, v) => { try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} };\nfunction syncCfg(){ const c = lsGet(SYNC_LS, null); return c && c.bar && SYNC_URL ? c : null; }\nlet syncQ = lsGet(SYNCQ_LS, []), syncErr = false, syncBusy = false;\nfunction syncEnqueue(coll, id, deleted){\n  if(db || !syncCfg()) return;\n  syncQ = syncQ.filter(x => !(x.coll === coll && x.id === id));\n  syncQ.push({coll, id, deleted: !!deleted}); lsSet(SYNCQ_LS, syncQ); setTimeout(syncFlush, 300);\n}\nfunction syncHeaders(c){ // ancienne clé « anon » (JWT) : aussi en Authorization ; nouvelle clé « publishable » : apikey seulement\n  const h = {\"apikey\": SYNC_ANON, \"x-bar-key\": c.bar, \"Content-Type\": \"application/json\"};\n  if(SYNC_ANON.startsWith(\"eyJ\")) h.Authorization = \"Bearer \" + SYNC_ANON; return h; }\nasync function syncFlush(){\n  const c = syncCfg(); if(!c || syncBusy) return;\n  syncBusy = true;\n  try{\n    while(syncQ.length){\n      const batch = syncQ.slice(0, 200);\n      const rows = batch.map(x => ({bar: c.bar, coll: x.coll, id: x.id, deleted: x.deleted || !S[x.coll][x.id], data: x.deleted ? null : (S[x.coll][x.id] || null)}));\n      const r = await fetch(`${SYNC_URL}/rest/v1/caisse_docs?on_conflict=bar,coll,id`, {method:\"POST\", headers:{...syncHeaders(c), \"Prefer\":\"resolution=merge-duplicates,return=minimal\"}, body: JSON.stringify(rows)});\n      if(!r.ok) throw new Error(\"HTTP \" + r.status);\n      syncQ = syncQ.slice(batch.length); lsSet(SYNCQ_LS, syncQ);\n    }\n    syncErr = false;\n  }catch(e){ syncErr = true; }\n  syncBusy = false; setSync();\n}\nasync function syncPull(){\n  const c = syncCfg(); if(!c || document.hidden) return;\n  try{\n    let since = lsGet(SYNCLAST_LS, \"1970-01-01T00:00:00Z\"), changed = false, more = true;\n    // marge d'une minute : une ligne validée en retard n'est pas perdue (réappliquer est sans effet)\n    let from = new Date(new Date(since).getTime() - 60000).toISOString();\n    while(more){\n      const r = await fetch(`${SYNC_URL}/rest/v1/caisse_docs?select=coll,id,data,deleted,updated_at&bar=eq.${encodeURIComponent(c.bar)}&updated_at=gt.${encodeURIComponent(from)}&order=updated_at.asc&limit=1000`, {headers: syncHeaders(c)});\n      if(!r.ok) throw new Error(\"HTTP \" + r.status);\n      const rows = await r.json();\n      rows.forEach(row => {\n        if(!S[row.coll] || syncQ.some(x => x.coll === row.coll && x.id === row.id)) return;\n        if(row.deleted) delete S[row.coll][row.id]; else S[row.coll][row.id] = row.data;\n        changed = true; if(row.updated_at > since) since = row.updated_at;\n      });\n      more = rows.length === 1000; if(more) from = rows[rows.length-1].updated_at;\n    }\n    lsSet(SYNCLAST_LS, since); syncErr = false;\n    if(changed){ saveLocal(); render(); }\n  }catch(e){ syncErr = true; }\n  setSync();\n}\nfunction newBarKey(){ const a = new Uint8Array(15); crypto.getRandomValues(a); return Array.from(a, b => \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\"[b % 32]).join(\"\").replace(/(.{5})(?=.)/g, \"$1-\"); }\nfunction syncStartAll(){ COLLS.forEach(c => Object.keys(S[c]).forEach(id => syncQ.push({coll:c, id, deleted:false}))); lsSet(SYNCQ_LS, syncQ); syncFlush().then(syncPull); }\n\nfunction setSync(){\n  const el = $(\"#sync\");\n  let cls=\"\", txt;\n  const sc = syncCfg();\n  if(!db && sc){ cls = syncQ.length || syncErr ? \"off\" : \"ok\"; txt = syncErr ? \"Hors ligne\" + (syncQ.length?` · ${syncQ.length} en attente`:\"\") : syncQ.length ? `${syncQ.length} à envoyer` : \"Synchronisé\"; }\n  else if(!db){ cls=\"off\"; txt=\"Sur ce téléphone\"; }\n  else if(queue.length){ cls=\"off\"; txt=`${queue.length} en attente`; }\n  else { cls=\"ok\"; txt=\"Enregistré\"; }\n  el.innerHTML = `<span class=\"dot ${cls}\"></span><span>${txt}</span>`;\n}\nfunction subscribe(){\n  const since = dayKey(addDays(new Date(), -100));\n  const queries = {\n    products: db.collection(\"products\"), tabs: db.collection(\"tabs\"), settings: db.collection(\"settings\"),\n    charges: db.collection(\"charges\").where(\"day\",\">=\",since), moves: db.collection(\"moves\").where(\"day\",\">=\",since),\n    tickets: db.collection(\"tickets\").where(\"day\",\">=\",since),\n    apparts: db.collection(\"apparts\"), locations: db.collection(\"locations\"),\n    shifts: db.collection(\"shifts\").where(\"day\",\">=\",since)\n  };\n  Object.entries(queries).forEach(([coll,q])=>{\n    q.onSnapshot(snap=>{\n      const m = {}; snap.docs.forEach(d=>{ m[d.id] = d.data(); });\n      // garder les données plus anciennes déjà chargées (tickets hors fenêtre) et les écritures en attente\n      if(coll === \"tickets\" || coll === \"charges\" || coll === \"moves\" || coll === \"shifts\"){\n        Object.entries(S[coll]).forEach(([id,v])=>{ if(v.day < since) m[id] = v; });\n      }\n      S[coll] = m;\n      queue.filter(o=>o.coll===coll).forEach(applyLocal);\n      online = true; loaded = true; saveLocal(); setSync(); render();\n    }, err=>{ setSync(); });\n  });\n}\n\n/* ---------- état de l'interface ---------- */\nlet tab = \"caisse\";\ntry{ const h = location.hash.slice(1); if([\"caisse\",\"tables\",\"stock\",\"chiffres\",\"loc\",\"plus\"].includes(h)) tab = h; }catch(e){}\nlet cat = \"Tout\";\nlet cart = [];              // {pid,name,price,cost,qty}\nlet period = {mode:\"jour\", ref:new Date()};\n\nconst products = () => Object.entries(S.products).map(([id,p])=>({id,...p})).filter(p=>!p.hidden)\n  .sort((a,b)=> (CATS.indexOf(a.cat)-CATS.indexOf(b.cat)) || ((a.order??999)-(b.order??999)) || a.name.localeCompare(b.name));\nconst barName = () => (S.settings.main && S.settings.main.barName) || \"Caisse du Bar\";\nconst cartTotal = c => c.reduce((s,l)=>s+l.price*l.qty,0);\nconst stockState = p => p.stock == null ? null : p.stock <= 0 ? \"out\" : p.stock <= (p.alert ?? 6) ? \"low\" : \"ok\";\n\n/* ---------- rendu ---------- */\nfunction render(){\n  initRole();\n  $(\"#brand\").textContent = barName();\n  const rb = $(\"#rolebtn\"); rb.textContent = (role===\"staff\" ? \"🔒 \" : \"\") + ROLE_NAMES[role]; rb.className = \"role\" + (role===\"staff\" ? \"\" : \" admin\");\n  document.querySelectorAll(\"#tabs button\").forEach(b=>b.setAttribute(\"aria-current\", b.dataset.tab===tab));\n  const nTabs = Object.keys(S.tabs).length;\n  $(\"#tabcount\").innerHTML = nTabs ? `<span class=\"badge-n\">${nTabs}</span>` : \"\";\n  const v = $(\"#view\"); const st = v.scrollTop;\n  v.innerHTML = ((tab===\"chiffres\" || tab===\"loc\") && role===\"staff\") ? viewLocked()\n    : ({caisse:viewCaisse, tables:viewTables, stock:viewStock, chiffres:viewChiffres, loc:viewLoc, plus:viewPlus})[tab]();\n  v.scrollTop = st;\n}\n\nfunction viewLocked(){\n  return `<div class=\"empty\"><p><b>Réservé au patron et à la gérante.</b></p><p>Le chiffre d'affaires et les locations s'affichent après avoir entré un code.</p><button class=\"btn pri\" data-act=\"role\">Entrer un code</button></div>`;\n}\nfunction installNote(){\n  if(!canAdmin()) return `<div class=\"empty\">La carte du bar n'est pas encore installée. Demandez à l'administrateur de l'installer.</div>`;\n  return `<div class=\"empty\"><p><b>La carte du bar n'est pas encore installée.</b></p>\n  <p>Elle contient vos ${CARTE.length} consommations avec leurs prix de vente.</p>\n  <button class=\"btn pri\" data-act=\"install\">Installer la carte</button></div>`;\n}\n\nfunction viewCaisse(){\n  const ps = products();\n  if(!ps.length) return installNote();\n  const cats = [\"Tout\", ...CATS.filter(c=>ps.some(p=>p.cat===c))];\n  const shown = cat===\"Tout\" ? ps : ps.filter(p=>p.cat===cat);\n  const inCart = {}; cart.forEach(l=>{ inCart[l.pid]=(inCart[l.pid]||0)+l.qty; });\n  const tot = cartTotal(cart), n = cart.reduce((s,l)=>s+l.qty,0);\n  return serviceBar() + `<div class=\"chips\">${cats.map(c=>`<button class=\"chip\" data-cat=\"${esc(c)}\" aria-pressed=\"${c===cat}\">${esc(c)}</button>`).join(\"\")}</div>\n  <div class=\"grid\">${shown.map(p=>{\n    const s = stockState(p);\n    const price = p.priceMax ? `${fcfa(p.price).replace(\" F\",\"\")}–${fcfa(p.priceMax)}` : fcfa(p.price);\n    return `<button class=\"prod\" data-add=\"${p.id}\">\n      ${inCart[p.id]?`<span class=\"qty num\">${inCart[p.id]}</span>`:\"\"}\n      ${s?`<span class=\"st num ${s===\"ok\"?\"\":s}\">${s===\"out\"?\"Épuisé\":p.stock}</span>`:\"\"}\n      <span class=\"nm\">${esc(p.name)}</span>\n      <span class=\"pr num\">${price}</span>\n      <span class=\"eu num\">${p.priceMax?`${eur(p.price).replace(\" €\",\"\")}–${eur(p.priceMax)}`:eur(p.price)}</span>\n    </button>`; }).join(\"\")}</div>\n  <div class=\"cartbar\">\n    <div class=\"tot\"><b class=\"num\">${fcfa(tot)}</b><span class=\"num\">${eur(tot)} · ${n} article${n>1?\"s\":\"\"}</span></div>\n    <button class=\"btn\" data-act=\"cart\" ${n?\"\":\"disabled\"}>Voir</button>\n    <button class=\"btn pri\" data-act=\"pay\" ${n?\"\":\"disabled\"}>Encaisser</button>\n  </div>`;\n}\n\n/* --- heures de travail (pointage du personnel) --- */\nconst SHIFTDEV_LS = \"caisse-bar.pointage\"; // ce téléphone sert au pointage : proposer le début de service à l'ouverture\nconst shifts = () => Object.entries(S.shifts).map(([id,x])=>({id,...x})).filter(x=>!x.deleted);\nconst openShifts = () => shifts().filter(x=>!x.end).sort((a,b)=>a.start-b.start);\nconst shiftMs = x => Math.max(0, (x.end || Date.now()) - x.start);\nconst fmtDur = ms => { const m = Math.round(ms/60000); return `${Math.floor(m/60)} h ${pad(m%60)}`; };\nconst staffNames = () => [...new Set(shifts().sort((a,b)=>b.start-a.start).map(x=>x.name))];\nfunction serviceBar(){\n  const op = openShifts();\n  return `<div class=\"svc\">${op.map(x=>`<div class=\"svcrow\"><span class=\"dot ok\"></span><span class=\"main\"><b>${esc(x.name)}</b> en service depuis ${fmtTime(x.start)}${new Date(x.start).toDateString()!==new Date().toDateString()?\" (hier)\":\"\"}</span>\n    <button class=\"btn sm\" data-shiftend=\"${x.id}\">Fin de service</button></div>`).join(\"\")}\n    <button class=\"btn sm ghost\" data-act=\"shiftstart\">${op.length?\"+ Autre personne\":\"Commencer mon service\"}</button></div>`;\n}\nfunction showShiftStart(auto){\n  const names = staffNames();\n  openModal(`<h2>${auto?\"Qui commence son service ?\":\"Commencer un service\"}</h2>\n  <p style=\"color:var(--muted)\">L'heure de début est enregistrée maintenant. Touchez « Fin de service » en partant.</p>\n  ${names.length?`<div class=\"chips\" style=\"flex-wrap:wrap\">${names.map(n=>`<button class=\"chip\" data-shiftname=\"${esc(n)}\">${esc(n)}</button>`).join(\"\")}</div>`:\"\"}\n  <div class=\"form\"><label class=\"f\">${names.length?\"Ou un autre prénom\":\"Prénom\"}<input id=\"shiftname\" autocomplete=\"off\" placeholder=\"Ex. Marie\"></label>\n  <button class=\"btn pri\" data-act=\"shiftgo\">Commencer le service</button>${auto?`<button class=\"btn ghost\" data-act=\"close\">Plus tard</button>`:\"\"}</div>`, {kind:\"shiftstart\"});\n}\nfunction startShift(name){\n  name = (name||\"\").trim(); if(!name){ toast(\"Indiquez le prénom.\"); return; }\n  if(openShifts().some(x=>x.name.toLowerCase()===name.toLowerCase())){ toast(`${name} est déjà en service.`); return; }\n  const now = Date.now(); write(\"set\",\"shifts\",uid(),{name, start:now, end:null, day:dayKey(new Date(now))});\n  try{ localStorage.setItem(SHIFTDEV_LS, \"1\"); }catch(e){}\n  closeModal(); toast(`Bon service, ${name} ! Début à ${fmtTime(now)}.`); render();\n}\nfunction showShiftEdit(id){\n  const x = S.shifts[id]; if(!x) return; const t = ts => ts ? fmtTime(ts) : \"\";\n  openModal(`<h2>Corriger un service</h2><div class=\"form\">\n  <label class=\"f\">Prénom<input id=\"sename\" value=\"${esc(x.name)}\"></label>\n  <label class=\"f\">Date de début<input id=\"seday\" type=\"date\" value=\"${dayKey(new Date(x.start))}\"></label>\n  <div class=\"two\"><label class=\"f\">Début<input id=\"sestart\" type=\"time\" value=\"${t(x.start)}\"></label><label class=\"f\">Fin${x.end?\"\":\" (en cours)\"}<input id=\"seend\" type=\"time\" value=\"${t(x.end)}\"></label></div>\n  <p class=\"note\">Si la fin est avant le début, le service se termine le lendemain.</p>\n  <button class=\"btn pri\" data-act=\"saveshift\">Enregistrer</button>\n  <button class=\"btn danger\" data-act=\"delshift\">Supprimer ce service</button></div>`, {kind:\"shiftedit\", id});\n}\nfunction shiftSection(from, to){\n  const a = dayKey(from), z = dayKey(to);\n  const xs = shifts().filter(x=>x.day>=a && x.day<=z).sort((p,q)=>q.start-p.start);\n  let h = `<h3>Heures de travail</h3>`;\n  if(!xs.length) return h + `<div class=\"note\">Aucun service pointé sur cette période. Le serveur touche « Commencer mon service » dans la Caisse en arrivant, et « Fin de service » en partant.</div>`;\n  const per = {}; xs.forEach(x=>{ const k=x.name; per[k]=per[k]||{ms:0,n:0}; per[k].ms+=shiftMs(x); per[k].n++; });\n  h += `<div class=\"list\">${Object.entries(per).sort((p,q)=>q[1].ms-p[1].ms).map(([n,v])=>`<div class=\"li\"><div class=\"main\"><b>${esc(n)}</b><small>${v.n} service${v.n>1?\"s\":\"\"}</small></div><div class=\"right\"><b class=\"num\">${fmtDur(v.ms)}</b></div></div>`).join(\"\")}</div>\n  <h3>Détail des services</h3><div class=\"list\">${xs.map(x=>{ const long = shiftMs(x) > 14*3600000;\n    return `<button class=\"li\" data-shiftedit=\"${x.id}\"><div class=\"main\"><b>${esc(x.name)}</b><small>${period.mode===\"jour\"?\"\":fmtDay(new Date(x.start))+\" · \"}${fmtTime(x.start)} → ${x.end?fmtTime(x.end):\"en cours\"}</small></div>\n    <div class=\"right\"><b class=\"num\">${fmtDur(shiftMs(x))}</b>${long?`<br><span class=\"pill low\">À vérifier</span>`:\"\"}</div></button>`; }).join(\"\")}</div>\n  <p class=\"note\">Touchez un service pour corriger l'heure ou le supprimer (oubli de pointage).</p>`;\n  return h;\n}\n\nfunction viewTables(){\n  const tabs = Object.entries(S.tabs).map(([id,t])=>({id,...t})).sort((a,b)=>a.opened-b.opened);\n  let h = `<h2>Commandes en cours</h2>`;\n  if(!tabs.length) return h + `<div class=\"note\">Aucune table ouverte. Dans la Caisse, choisissez les consommations puis touchez « Voir » et « Mettre sur une table » pour ouvrir une addition.</div>`;\n  h += `<div class=\"list\">${tabs.map(t=>{ const tot = cartTotal(t.items||[]); const n=(t.items||[]).reduce((s,l)=>s+l.qty,0);\n    return `<button class=\"li\" data-tabopen=\"${t.id}\"><div class=\"main\"><b>${esc(t.name)}</b><small>Ouverte à ${fmtTime(t.opened)} · ${n} article${n>1?\"s\":\"\"}</small></div>\n    <div class=\"right\"><b class=\"num\">${fcfa(tot)}</b><br><small class=\"num\">${eur(tot)}</small></div></button>`; }).join(\"\")}</div>`;\n  return h;\n}\n\nfunction viewStock(){\n  const ps = products();\n  if(!ps.length) return installNote();\n  const low = ps.filter(p=>[\"low\",\"out\"].includes(stockState(p)));\n  const unknown = ps.filter(p=>p.stock==null).length;\n  let h = `<h2>Stock</h2>`;\n  if(unknown) h += `<div class=\"note\">Le stock de ${unknown} produit${unknown>1?\"s\":\"\"} n'est pas encore compté. Touchez un produit pour faire l'inventaire ou enregistrer une livraison.</div>`;\n  if(low.length) h += `<h3>À commander</h3><div class=\"list\">${low.map(p=>`<button class=\"li\" data-stk=\"${p.id}\"><div class=\"main\"><b>${esc(p.name)}</b><small>Seuil d'alerte : ${p.alert ?? 6}</small></div><span class=\"pill ${stockState(p)} num\">${p.stock<=0?\"Épuisé\":p.stock+\" restants\"}</span></button>`).join(\"\")}</div>`;\n  CATS.forEach(c=>{\n    const g = ps.filter(p=>p.cat===c); if(!g.length) return;\n    h += `<h3>${esc(c)}</h3><div class=\"list\">${g.map(p=>{ const s=stockState(p);\n      return `<button class=\"li\" data-stk=\"${p.id}\"><div class=\"main\"><b>${esc(p.name)}</b><small class=\"num\">${p.cost && canCost()?`Achat ${fcfa(p.cost)} · `:\"\"}Vente ${fcfa(p.price)}</small></div>\n      ${s?`<span class=\"pill ${s} num\">${p.stock}</span>`:`<span class=\"pill\">à compter</span>`}</button>`; }).join(\"\")}</div>`;\n  });\n  const recent = Object.values(S.moves).sort((a,b)=>b.ts-a.ts).slice(0,10);\n  if(recent.length) h += `<h3>Dernières livraisons et inventaires</h3><div class=\"list\">${recent.map(m=>`<div class=\"li\"><div class=\"main\"><b>${esc(m.name)}</b><small>${fmtDay(new Date(m.ts))} à ${fmtTime(m.ts)}</small></div><div class=\"right num\">${m.type===\"inv\"?\"Inventaire : \"+m.qty:\"+\"+m.qty}</div></div>`).join(\"\")}</div>`;\n  return h;\n}\n\n/* --- chiffres --- */\nfunction periodRange(){\n  const r = new Date(period.ref); r.setHours(0,0,0,0);\n  if(period.mode===\"jour\") return {from:r, to:r, label: fmtDay(r)};\n  if(period.mode===\"semaine\"){\n    const mon = addDays(r, -((r.getDay()+6)%7)), sun = addDays(mon,6);\n    return {from:mon, to:sun, label:`Semaine du ${mon.getDate()} ${MOIS[mon.getMonth()].slice(0,4)}. au ${sun.getDate()} ${MOIS[sun.getMonth()].slice(0,4)}.`};\n  }\n  const f = new Date(r.getFullYear(), r.getMonth(), 1), t = new Date(r.getFullYear(), r.getMonth()+1, 0);\n  return {from:f, to:t, label:`${MOIS[f.getMonth()][0].toUpperCase()+MOIS[f.getMonth()].slice(1)} ${f.getFullYear()}`};\n}\nfunction stats(from,to){\n  const a = dayKey(from), b = dayKey(to);\n  const tks = Object.entries(S.tickets).map(([id,t])=>({id,...t})).filter(t=>t.day>=a && t.day<=b && !t.cancelled).sort((x,y)=>x.ts-y.ts);\n  const ch = Object.values(S.charges).filter(c=>c.day>=a && c.day<=b && c.scope!==\"appart\");\n  let ca=0, cost=0, costKnown=true; const byProd={};\n  tks.forEach(t=>{ ca+=t.total; (t.items||[]).forEach(l=>{\n    if(l.cost) cost+=l.cost*l.qty; else costKnown=false;\n    const k=l.name; byProd[k]=byProd[k]||{name:k,qty:0,ca:0}; byProd[k].qty+=l.qty; byProd[k].ca+=l.price*l.qty; }); });\n  const charges = ch.reduce((s,c)=>s+(+c.amount||0),0);\n  return {tks, ca, cost, costKnown: costKnown && tks.length>0, charges, ch, top:Object.values(byProd).sort((x,y)=>y.ca-x.ca)};\n}\nfunction barChart(bars){\n  const W=340,H=150,padL=4,padB=20,padT=16; const max=Math.max(1,...bars.map(b=>b.v));\n  const bw=(W-padL*2)/bars.length;\n  let s=`<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Chiffre d'affaires par jour\">`;\n  s+=`<line x1=\"0\" x2=\"${W}\" y1=\"${H-padB}\" y2=\"${H-padB}\" stroke=\"var(--line)\"/>`;\n  const every = bars.length>16 ? 5 : 1;\n  bars.forEach((b,i)=>{\n    const h=(H-padB-padT)*b.v/max, x=padL+i*bw+bw*.15, w=bw*.7, y=H-padB-h;\n    s+=`<rect x=\"${x.toFixed(1)}\" y=\"${y.toFixed(1)}\" width=\"${w.toFixed(1)}\" height=\"${Math.max(h,b.v?1.5:0).toFixed(1)}\" rx=\"2\" fill=\"${b.cur?\"var(--accent)\":\"var(--muted)\"}\" opacity=\"${b.cur?1:.55}\"/>`;\n    if(i%every===0 || b.cur) s+=`<text x=\"${(x+w/2).toFixed(1)}\" y=\"${H-5}\" font-size=\"10\" text-anchor=\"middle\" fill=\"var(--muted)\" font-family=\"var(--f-body)\">${esc(b.l)}</text>`;\n  });\n  const mi = bars.reduce((m,b,i)=>b.v>bars[m].v?i:m,0);\n  if(bars[mi].v>0){ const x=padL+mi*bw+bw/2; s+=`<text x=\"${Math.min(Math.max(x,30),W-30).toFixed(1)}\" y=\"11\" font-size=\"10\" text-anchor=\"middle\" fill=\"var(--fg)\" font-weight=\"700\" font-family=\"var(--f-body)\">${esc(fcfa(bars[mi].v))}</text>`; }\n  return s+`</svg>`;\n}\n/* ---------- location d'appartements ---------- */\nconst nightsBetween = (a, b) => Math.round((parseDay(b) - parseDay(a)) / 86400000);\nfunction rentPrice(ap, nights){\n  const base = (ap.dayPrice||0) * nights;\n  const pct = nights >= 30 ? (ap.monthDisc||0) : nights >= 7 ? (ap.weekDisc||0) : 0;\n  return {base, pct, auto: Math.round(base*pct/100)};\n}\nfunction nightsIn(l, from, to){ // nuits de la location qui tombent dans la période [from, to]\n  const a = l.start > dayKey(from) ? l.start : dayKey(from);\n  const endIncl = dayKey(addDays(parseDay(l.end), -1)); const b = endIncl < dayKey(to) ? endIncl : dayKey(to);\n  return b < a ? 0 : nightsBetween(a, b) + 1;\n}\nconst apparts = () => Object.entries(S.apparts).map(([id,a])=>({id,...a})).filter(a=>!a.hidden).sort((x,y)=>x.name.localeCompare(y.name));\nconst locs = () => Object.entries(S.locations).map(([id,l])=>({id,...l})).filter(l=>!l.cancelled);\nfunction locStats(from, to){\n  const a = dayKey(from), z = dayKey(to); let ca = 0, nights = 0;\n  locs().forEach(l => { const n = nightsIn(l, from, to); if(n){ ca += l.total * n / l.nights; nights += n; } });\n  const ch = Object.values(S.charges).filter(c=>c.day>=a && c.day<=z && c.scope===\"appart\");\n  const charges = ch.reduce((s,c)=>s+(+c.amount||0),0);\n  const days = nightsBetween(a, z) + 1, nb = apparts().length;\n  return {ca: Math.round(ca), nights, charges, ch, occ: nb ? Math.round(nights / (nb*days) * 100) : 0};\n}\nfunction viewLoc(){\n  const {from,to,label} = periodRange(); const st = locStats(from,to); const aps = apparts(); const today = dayKey(new Date());\n  let h = `<h2>Locations</h2>`;\n  if(!aps.length) return h + `<div class=\"empty\"><p><b>Aucun logement pour l'instant.</b></p>${canAdmin()?`<p>Ajoutez vos appartements avec leur prix à la nuit et leurs réductions.</p><button class=\"btn pri\" data-act=\"newappart\">Ajouter un logement</button>`:`<p>Demandez à l'administrateur d'ajouter les logements.</p>`}</div>`;\n  h += `<button class=\"btn pri wide\" data-act=\"newloc\">Nouvelle location</button>\n  <div class=\"seg\" style=\"margin-top:14px\">${[\"jour\",\"semaine\",\"mois\"].map(m=>`<button data-mode=\"${m}\" aria-pressed=\"${period.mode===m}\">${m[0].toUpperCase()+m.slice(1)}</button>`).join(\"\")}</div>\n  <div class=\"period\"><button class=\"btn sm ghost\" data-shift=\"-1\" aria-label=\"Période précédente\">‹</button><b>${esc(label)}</b><button class=\"btn sm ghost\" data-shift=\"1\" aria-label=\"Période suivante\">›</button></div>\n  <div class=\"kpis\">\n    <div class=\"kpi big\"><div class=\"l\">Bénéfice net des locations</div><div class=\"v num\">${fcfa(st.ca - st.charges)}</div><div class=\"s num\">${eur(st.ca - st.charges)}</div></div>\n    <div class=\"kpi\"><div class=\"l\">Loyers</div><div class=\"v num\">${fcfa(st.ca)}</div><div class=\"s num\">${st.nights} nuit${st.nights>1?\"s\":\"\"}</div></div>\n    <div class=\"kpi\"><div class=\"l\">Charges</div><div class=\"v num\">${fcfa(st.charges)}</div><div class=\"s num\">Occupation ${st.occ} %</div></div>\n  </div>\n  <p class=\"note\">Les loyers sont comptés nuit par nuit : une location d'un mois compte pour chaque jour du mois.</p>`;\n  const cur = locs().filter(l=>l.end > today).sort((x,y)=>x.start.localeCompare(y.start));\n  h += `<h3>En cours et à venir</h3>` + (cur.length ? `<div class=\"list\">${cur.map(l=>{ const ap=S.apparts[l.appart]||{name:\"?\"}; const now=l.start<=today;\n    return `<button class=\"li\" data-locopen=\"${l.id}\"><div class=\"main\"><b>${esc(ap.name)} · ${esc(l.client||\"Client\")}</b><small>${fmtDay(parseDay(l.start))} → ${fmtDay(parseDay(l.end))} · ${l.nights} nuit${l.nights>1?\"s\":\"\"}</small></div>\n    <div class=\"right\"><b class=\"num\">${fcfa(l.total)}</b><br><span class=\"pill ${l.paid>=l.total?\"ok\":\"low\"}\">${l.paid>=l.total?\"Payée\":now?\"En cours · à payer\":\"À payer\"}</span></div></button>`; }).join(\"\")}</div>` : `<div class=\"note\">Aucune location en cours.</div>`);\n  const past = locs().filter(l=>l.end <= today && nightsIn(l,from,to)).sort((x,y)=>y.start.localeCompare(x.start));\n  if(past.length) h += `<h3>Terminées sur la période</h3><div class=\"list\">${past.map(l=>`<button class=\"li\" data-locopen=\"${l.id}\"><div class=\"main\"><b>${esc((S.apparts[l.appart]||{}).name||\"?\")} · ${esc(l.client||\"Client\")}</b><small>${fmtDay(parseDay(l.start))} → ${fmtDay(parseDay(l.end))}</small></div><div class=\"right num\">${fcfa(l.total)}${l.paid<l.total?`<br><span class=\"pill low\">Reste ${fcfa(l.total-l.paid)}</span>`:\"\"}</div></button>`).join(\"\")}</div>`;\n  h += `<h3>Charges des logements</h3><div class=\"note\">Eau, électricité, internet, ménage, entretien… déduites du bénéfice des locations.</div>\n  <button class=\"btn wide\" data-act=\"addlcharge\">Ajouter une charge de logement</button>`;\n  if(st.ch.length) h += `<div class=\"list\" style=\"margin-top:10px\">${st.ch.sort((x,y)=>y.day.localeCompare(x.day)).map(c=>`<div class=\"li\"><div class=\"main\"><b>${esc(c.label)}</b><small>${fmtDay(parseDay(c.day))}${c.appart&&S.apparts[c.appart]?\" · \"+esc(S.apparts[c.appart].name):\"\"}</small></div><div class=\"right num\">${fcfa(c.amount)}</div></div>`).join(\"\")}</div>`;\n  h += `<h3>Logements</h3><div class=\"list\">${aps.map(a=>`<button class=\"li\" ${canAdmin()?`data-appedit=\"${a.id}\"`:\"\"}><div class=\"main\"><b>${esc(a.name)}</b><small class=\"num\">${a.weekDisc?`−${a.weekDisc} % à la semaine`:\"\"}${a.weekDisc&&a.monthDisc?\" · \":\"\"}${a.monthDisc?`−${a.monthDisc} % au mois`:\"\"}</small></div><div class=\"right\"><b class=\"num\">${fcfa(a.dayPrice)}</b><br><small class=\"num\">la nuit · ${eur(a.dayPrice)}</small></div></button>`).join(\"\")}</div>`;\n  if(canAdmin()) h += `<div class=\"row wrap\" style=\"margin-top:10px\"><button class=\"btn\" data-act=\"newappart\">Ajouter un logement</button></div>`;\n  return h;\n}\nfunction showAppartEdit(id){\n  const a = id ? S.apparts[id] : {name:\"\", dayPrice:\"\", weekDisc:\"\", monthDisc:\"\"};\n  openModal(`<h2>${id?\"Modifier le logement\":\"Nouveau logement\"}</h2><div class=\"form\">\n  <label class=\"f\">Nom<input id=\"aname\" value=\"${esc(a.name)}\" placeholder=\"Ex. Appartement 1, Studio\"></label>\n  <label class=\"f\">Prix de la nuit (F)<input id=\"aprice\" type=\"number\" inputmode=\"numeric\" value=\"${a.dayPrice||\"\"}\"></label>\n  <div class=\"two\"><label class=\"f\">Réduction à la semaine (%)<input id=\"aweek\" type=\"number\" inputmode=\"numeric\" value=\"${a.weekDisc||\"\"}\" placeholder=\"dès 7 nuits\"></label>\n  <label class=\"f\">Réduction au mois (%)<input id=\"amonth\" type=\"number\" inputmode=\"numeric\" value=\"${a.monthDisc||\"\"}\" placeholder=\"dès 30 nuits\"></label></div>\n  <button class=\"btn pri\" data-act=\"saveappart\">Enregistrer</button>${id?`<button class=\"btn danger\" data-act=\"hideappart\">Retirer ce logement</button>`:\"\"}</div>`, {kind:\"appart\", id});\n}\nfunction locPreview(){\n  const ap = S.apparts[$(\"#lapp\").value]; const st = $(\"#lstart\").value, en = $(\"#lend\").value; const box = $(\"#lprev\");\n  if(!ap || !st || !en || en <= st){ box.textContent = \"Choisissez le logement et les dates (le départ après l'arrivée).\"; modalState.calc = null; return; }\n  const n = nightsBetween(st, en); const p = rentPrice(ap, n); const extra = canCost() ? Math.max(0, +($(\"#lextra\").value||0)) : 0;\n  const total = Math.max(0, p.base - p.auto - extra);\n  const clash = locs().find(l => l.appart === $(\"#lapp\").value && l.id !== modalState.id && l.start < en && l.end > st);\n  modalState.calc = {nights:n, base:p.base, pct:p.pct, auto:p.auto, extra, total};\n  box.innerHTML = `${n} nuit${n>1?\"s\":\"\"} × ${fcfa(ap.dayPrice)} = ${fcfa(p.base)}${p.pct?`<br>Réduction ${n>=30?\"au mois\":\"à la semaine\"} (${p.pct} %) : −${fcfa(p.auto)}`:\"\"}${extra?`<br>Réduction accordée : −${fcfa(extra)}`:\"\"}<br><b style=\"font-size:18px\">Total : ${fcfa(total)}</b> · ${eur(total)}${clash?`<br><span style=\"color:var(--bad)\">Attention : ce logement est déjà loué à ${esc(clash.client||\"un client\")} sur ces dates.</span>`:\"\"}`;\n}\nfunction showLocEdit(id){\n  const l = id ? S.locations[id] : {appart: apparts()[0].id, start: dayKey(new Date()), end: dayKey(addDays(new Date(),1)), client:\"\", phone:\"\", paid:0, extra:0};\n  openModal(`<h2>${id?\"Modifier la location\":\"Nouvelle location\"}</h2><div class=\"form\">\n  <label class=\"f\">Logement<select id=\"lapp\">${apparts().map(a=>`<option value=\"${a.id}\" ${a.id===l.appart?\"selected\":\"\"}>${esc(a.name)} · ${fcfa(a.dayPrice)} la nuit</option>`).join(\"\")}</select></label>\n  <div class=\"two\"><label class=\"f\">Arrivée<input id=\"lstart\" type=\"date\" value=\"${l.start}\"></label><label class=\"f\">Départ<input id=\"lend\" type=\"date\" value=\"${l.end}\"></label></div>\n  <div class=\"two\"><label class=\"f\">Client<input id=\"lclient\" value=\"${esc(l.client||\"\")}\" placeholder=\"Nom\"></label><label class=\"f\">Téléphone<input id=\"lphone\" type=\"tel\" value=\"${esc(l.phone||\"\")}\"></label></div>\n  ${canCost()?`<label class=\"f\">Réduction en plus (F, facultatif)<input id=\"lextra\" type=\"number\" inputmode=\"numeric\" value=\"${l.extra||\"\"}\"></label>`:\"\"}\n  <p class=\"note num\" id=\"lprev\"></p>\n  <div class=\"two\"><label class=\"f\">Déjà payé (F)<input id=\"lpaid\" type=\"number\" inputmode=\"numeric\" value=\"${l.paid||\"\"}\"></label>\n  <label class=\"f\">Paiement<select id=\"lpay\">${[\"Espèces\",\"Mobile Money\",\"Carte\",\"Virement\"].map(m=>`<option ${m===l.pay?\"selected\":\"\"}>${m}</option>`).join(\"\")}</select></label></div>\n  <button class=\"btn pri\" data-act=\"saveloc\">Enregistrer la location</button></div>`, {kind:\"loc\", id: id||null, calc:null});\n  locPreview();\n}\nfunction showLoc(id){\n  const l = S.locations[id]; const ap = S.apparts[l.appart]||{name:\"?\"};\n  openModal(`<h2>${esc(ap.name)}</h2><p>${esc(l.client||\"Client\")}${l.phone?` · <span class=\"num\">${esc(l.phone)}</span>`:\"\"}</p>\n  <div class=\"list\"><div class=\"li\"><div class=\"main\">Du ${fmtDay(parseDay(l.start))} au ${fmtDay(parseDay(l.end))}</div><div class=\"right num\">${l.nights} nuit${l.nights>1?\"s\":\"\"}</div></div>\n  <div class=\"li\"><div class=\"main\">Prix de base</div><div class=\"right num\">${fcfa(l.base)}</div></div>\n  ${l.auto?`<div class=\"li\"><div class=\"main\">Réduction ${l.nights>=30?\"au mois\":\"à la semaine\"} (${l.pct} %)</div><div class=\"right num\">−${fcfa(l.auto)}</div></div>`:\"\"}\n  ${l.extra?`<div class=\"li\"><div class=\"main\">Réduction accordée</div><div class=\"right num\">−${fcfa(l.extra)}</div></div>`:\"\"}\n  <div class=\"li\"><div class=\"main\"><b>Total</b></div><div class=\"right\"><b class=\"num\">${fcfa(l.total)}</b><br><small class=\"num\">${eur(l.total)}</small></div></div>\n  <div class=\"li\"><div class=\"main\">Payé (${esc(l.pay||\"\")})</div><div class=\"right num\">${fcfa(l.paid||0)}</div></div></div>\n  <div class=\"form\" style=\"margin-top:12px\">\n  ${l.paid<l.total?`<button class=\"btn pri wide\" data-act=\"locpaid\">Marquer comme payée (reste ${fcfa(l.total-(l.paid||0))})</button>`:\"\"}\n  ${NATIVE?`<button class=\"btn wide\" data-act=\"locprint\">Imprimer le reçu</button>`:\"\"}\n  <button class=\"btn wide\" data-act=\"locedit\">Modifier</button>\n  ${canCost()?`<button class=\"btn danger wide\" data-act=\"loccancel\">Annuler cette location</button>`:\"\"}</div>`, {kind:\"locview\", id});\n}\nfunction locAsTicket(l){\n  const ap = S.apparts[l.appart]||{name:\"Logement\"};\n  return {no:\"LOC\", ts:Date.now(), table: ap.name, client: l.client, items:[{qty:l.nights, name:`nuit(s) du ${l.start.split(\"-\").reverse().join(\"/\")} au ${l.end.split(\"-\").reverse().join(\"/\")}`, price: l.base / l.nights}],\n    subtotal: l.base, discount: (l.auto||0)+(l.extra||0), total: l.total, pay: l.pay||\"Espèces\", received: l.paid||0, change: 0};\n}\nfunction showAddLCharge(){\n  openModal(`<h2>Charge de logement</h2><div class=\"form\">\n  <label class=\"f\">Nature<input id=\"lclabel\" list=\"lcsugg\" placeholder=\"Ex. Électricité\"><datalist id=\"lcsugg\">${[\"Eau\",\"Électricité\",\"Internet\",\"Ménage\",\"Entretien\",\"Linge\",\"Gaz\",\"Taxe\"].map(x=>`<option value=\"${x}\">`).join(\"\")}</datalist></label>\n  <div class=\"two\"><label class=\"f\">Montant (F)<input id=\"lcamount\" type=\"number\" inputmode=\"numeric\"></label><label class=\"f\">Date<input id=\"lcday\" type=\"date\" value=\"${dayKey(new Date())}\"></label></div>\n  <label class=\"f\">Logement<select id=\"lcapp\"><option value=\"\">Tous les logements</option>${apparts().map(a=>`<option value=\"${a.id}\">${esc(a.name)}</option>`).join(\"\")}</select></label>\n  <button class=\"btn pri\" data-act=\"savelcharge\">Enregistrer</button></div>`, {kind:\"lcharge\"});\n}\n\nfunction viewChiffres(){\n  const {from,to,label} = periodRange();\n  const st = stats(from,to);\n  const n = st.tks.length;\n  let h = `<div class=\"seg\">${[\"jour\",\"semaine\",\"mois\"].map(m=>`<button data-mode=\"${m}\" aria-pressed=\"${period.mode===m}\">${m[0].toUpperCase()+m.slice(1)}</button>`).join(\"\")}</div>\n  <div class=\"period\"><button class=\"btn sm ghost\" data-shift=\"-1\" aria-label=\"Période précédente\">‹</button><b>${esc(label)}</b><button class=\"btn sm ghost\" data-shift=\"1\" aria-label=\"Période suivante\">›</button></div>\n  <div class=\"kpis\">\n    <div class=\"kpi big\"><div class=\"l\">Chiffre d'affaires</div><div class=\"v num\">${fcfa(st.ca)}</div><div class=\"s num\">${eur(st.ca)}</div></div>\n    <div class=\"kpi\"><div class=\"l\">Tickets</div><div class=\"v num\">${n}</div><div class=\"s num\">Panier moyen ${fcfa(n?st.ca/n:0)}</div></div>\n    <div class=\"kpi\"><div class=\"l\">Charges</div><div class=\"v num\">${fcfa(st.charges)}</div><div class=\"s num\">${eur(st.charges)}</div></div>`;\n  if(st.costKnown){\n    const marge = st.ca-st.cost, res = marge-st.charges;\n    h += `<div class=\"kpi\"><div class=\"l\">Marge sur boissons</div><div class=\"v num\">${fcfa(marge)}</div><div class=\"s num\">Achats ${fcfa(st.cost)} · ${st.ca?Math.round(marge/st.ca*100):0} %</div></div>\n    <div class=\"kpi\"><div class=\"l\">Bénéfice</div><div class=\"v num ${res<0?\"neg\":\"pos\"}\">${fcfa(res)}</div><div class=\"s num\">${eur(res)}</div></div>`;\n  }\n  h += `</div>`;\n  if(n && !st.costKnown) h += `<div class=\"note\">Pour voir la marge et le bénéfice, entrez le prix d'achat de chaque produit dans Réglages, puis Produits et prix.</div>`;\n  if(period.mode!==\"jour\"){\n    const bars=[]; const today=dayKey(new Date());\n    for(let d=new Date(from); d<=to; d=addDays(d,1)){ const k=dayKey(d);\n      bars.push({l: period.mode===\"semaine\" ? JOURS[d.getDay()].replace(\".\",\"\") : String(d.getDate()), v: st.tks.filter(t=>t.day===k).reduce((s,t)=>s+t.total,0), cur:k===today}); }\n    h += `<div class=\"chart\">${barChart(bars)}</div>`;\n  } else if(n){\n    const hrs={}; st.tks.forEach(t=>{ const x=new Date(t.ts).getHours(); hrs[x]=(hrs[x]||0)+t.total; });\n    const ks=Object.keys(hrs).map(Number); const lo=Math.min(...ks), hi=Math.max(...ks); const bars=[];\n    for(let x=lo;x<=hi;x++) bars.push({l:x+\"h\", v:hrs[x]||0, cur:false});\n    h += `<div class=\"chart\">${barChart(bars)}</div>`;\n  }\n  if(st.top.length) h += `<h3>Ventes par produit</h3><div class=\"list\">${st.top.map(p=>`<div class=\"li\"><div class=\"main\"><b>${esc(p.name)}</b><small class=\"num\">${p.qty} vendu${p.qty>1?\"s\":\"\"}</small></div><div class=\"right num\">${fcfa(p.ca)}</div></div>`).join(\"\")}</div>`;\n  if(canAdmin()){\n    const a = dayKey(from), z = dayKey(to);\n    const ev = Object.values(S.tickets).filter(t=>t.day>=a && t.day<=z && (t.cancelled || t.discount)).sort((x,y)=>y.ts-x.ts);\n    if(ev.length){\n      const totDisc = ev.filter(t=>!t.cancelled).reduce((s,t)=>s+(t.discount||0),0), totCanc = ev.filter(t=>t.cancelled).reduce((s,t)=>s+t.total,0);\n      h += `<h3>Annulations et réductions</h3><div class=\"note num\">Réductions : ${fcfa(totDisc)} · Tickets annulés : ${fcfa(totCanc)}</div><div class=\"list\">${ev.map(t=>t.cancelled\n        ? `<div class=\"li\"><div class=\"main\"><b>Annulé · N° ${esc(t.no)}</b><small>${fmtDay(new Date(t.cancelledAt||t.ts))} ${fmtTime(t.cancelledAt||t.ts)} · par ${esc(ROLE_NAMES[t.cancelledBy]||\"?\")} · ${esc(t.cancelReason||\"sans motif\")}</small></div><span class=\"pill out num\">${fcfa(t.total)}</span></div>`\n        : `<div class=\"li\"><div class=\"main\"><b>Réduction · N° ${esc(t.no)}</b><small>${fmtDay(new Date(t.ts))} ${fmtTime(t.ts)} · par ${esc(ROLE_NAMES[t.discountBy]||\"?\")}${t.discountReason?\" · \"+esc(t.discountReason):\"\"}</small></div><span class=\"pill low num\">−${fcfa(t.discount)}</span></div>`).join(\"\")}</div>`;\n    }\n  }\n  h += shiftSection(from, to);\n  if(n) h += `<h3>Tickets</h3><div class=\"list\">${st.tks.slice().reverse().map(t=>`<button class=\"li\" data-ticket=\"${t.id}\"><div class=\"main\"><b>N° ${esc(t.no)}${t.table?\" · \"+esc(t.table):\"\"}</b><small>${period.mode===\"jour\"?\"\":fmtDay(new Date(t.ts))+\" · \"}${fmtTime(t.ts)} · ${esc(t.pay)}</small></div><div class=\"right num\">${fcfa(t.total)}</div></button>`).join(\"\")}</div>`;\n  else h += `<div class=\"empty\">Aucune vente sur cette période.</div>`;\n  if(st.ch.length) h += `<h3>Charges de la période</h3><div class=\"list\">${st.ch.map(c=>`<div class=\"li\"><div class=\"main\"><b>${esc(c.label)}</b><small>${fmtDay(parseDay(c.day))}</small></div><div class=\"right num\">${fcfa(c.amount)}</div></div>`).join(\"\")}</div>`;\n  return h;\n}\n\nfunction viewPlus(){\n  const ps = products(); const s = S.settings.main || {};\n  const m = new Date(); const mk = dayKey(new Date(m.getFullYear(),m.getMonth(),1));\n  const ch = Object.entries(S.charges).map(([id,c])=>({id,...c})).filter(c=>c.day>=mk && c.scope!==\"appart\").sort((a,b)=>b.day.localeCompare(a.day));\n  let h = `<h2>Réglages</h2>`;\n  if(role===\"staff\") h += `<div class=\"note\">Vous êtes en mode Serveur. Les prix, les charges et le chiffre d'affaires sont réservés. <button class=\"btn sm\" data-act=\"role\">Entrer un code</button></div>`;\n  if(canAdmin()){\n    if(!hasAdminPin()) h += `<div class=\"note warn\"><b>Créez votre code administrateur.</b> Sans code, tout le monde peut changer les prix et voir le chiffre d'affaires.</div>`;\n    h += `<h3>Codes d'accès</h3>\n    <div class=\"form\"><label class=\"f\">${hasAdminPin()?\"Changer le code administrateur\":\"Code administrateur (4 chiffres ou plus)\"}<input id=\"newadmin\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\"></label>\n    <button class=\"btn\" data-act=\"setadmin\">Enregistrer le code administrateur</button>\n    <label class=\"f\">Code gérante (prix d'achat, réductions, annulation de tickets, chiffre d'affaires ; ne change pas les prix de vente)<input id=\"newgest\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"${s.gestPin?\"Un code est déjà actif\":\"Aucun code pour l'instant\"}\"></label>\n    <div class=\"row wrap\"><button class=\"btn\" data-act=\"setgest\">Enregistrer le code gérante</button>${s.gestPin?`<button class=\"btn danger\" data-act=\"delgest\">Supprimer ce droit</button>`:\"\"}</div></div>\n    <h3>Mon bar</h3>\n    <div class=\"form\"><label class=\"f\">Nom affiché sur les tickets<input id=\"barname\" value=\"${esc(s.barName||\"\")}\" placeholder=\"Ex. Bar Le Palmier\"></label>\n    <label class=\"f\">Phrase en bas du ticket<input id=\"footer\" value=\"${esc(s.footer||\"\")}\" placeholder=\"Merci de votre visite !\"></label>\n    <button class=\"btn\" data-act=\"savebar\">Enregistrer</button></div>\n    <h3>Charges du mois</h3>\n    <div class=\"note\">Loyer, électricité, salaires, glace… Elles sont déduites du bénéfice dans Chiffres.</div>\n    <button class=\"btn pri wide\" data-act=\"addcharge\">Ajouter une charge</button>\n    ${ch.length?`<div class=\"list\" style=\"margin-top:10px\">${ch.map(c=>`<div class=\"li\"><div class=\"main\"><b>${esc(c.label)}</b><small>${fmtDay(parseDay(c.day))}</small></div><div class=\"right num\">${fcfa(c.amount)}</div><button class=\"btn sm danger\" data-delcharge=\"${c.id}\" aria-label=\"Supprimer\">✕</button></div>`).join(\"\")}</div>`:\"\"}\n    <h3>Produits et prix</h3>\n    ${ps.length?`<div class=\"list\">${ps.map(p=>`<button class=\"li\" data-edit=\"${p.id}\"><div class=\"main\"><b>${esc(p.name)}</b><small>${esc(p.cat)}</small></div><div class=\"right num\">${fcfa(p.price)}${p.priceMax?\" à \"+fcfa(p.priceMax):\"\"}<br><small>${p.cost?\"achat \"+fcfa(p.cost):\"achat ?\"}</small></div></button>`).join(\"\")}</div>`:installNote()}\n    <div class=\"row wrap\" style=\"margin-top:10px\"><button class=\"btn\" data-act=\"newprod\">Ajouter un produit</button></div>`;\n  } else if(role===\"gest\"){\n    h += `<h3>Prix d'achat</h3><div class=\"note\">Ces prix sont confidentiels : seuls l'administrateur et la gérante les voient.</div>\n    <div class=\"list\">${ps.map(p=>`<button class=\"li\" data-costedit=\"${p.id}\"><div class=\"main\"><b>${esc(p.name)}</b><small class=\"num\">Vente ${fcfa(p.price)}</small></div><div class=\"right num\">${p.cost?\"achat \"+fcfa(p.cost):\"achat ?\"}</div></button>`).join(\"\")}</div>`;\n  }\n  if(NATIVE) h += `<h3>Imprimante Bluetooth</h3>\n  <div class=\"note\">${getPrinter()?`Imprimante choisie : <b>${esc(getPrinter().name||getPrinter().address)}</b>`:\"Aucune imprimante choisie.\"}</div>\n  <div class=\"row wrap\"><button class=\"btn\" data-act=\"pickprinter\">Choisir l'imprimante</button><button class=\"btn\" data-act=\"testprint\">Imprimer un test</button></div>\n  <label class=\"row\" style=\"margin-top:10px;gap:8px\"><input id=\"autoprint\" type=\"checkbox\" style=\"width:auto\" ${(()=>{try{return localStorage.getItem(\"caisse-bar.autoprint\")===\"1\"}catch(e){return false}})()?\"checked\":\"\"}> Imprimer le ticket automatiquement à chaque encaissement</label>`;\n  if(!db && SYNC_URL && canAdmin()){\n    const c = syncCfg();\n    h += `<h3>Synchronisation entre téléphones</h3>` + (c\n      ? `<div class=\"note\">Ce téléphone est relié au bar. Code de liaison : <b class=\"num\" style=\"font-family:var(--f-mono)\">${esc(c.bar)}</b><br>Entrez ce code sur votre propre téléphone pour suivre les ventes à distance.</div>\n         <button class=\"btn ghost\" data-act=\"syncoff\">Délier ce téléphone</button>`\n      : `<div class=\"note\">Reliez le téléphone de caisse et votre téléphone pour voir les ventes à distance. Il faut internet de temps en temps ; sans internet, la caisse continue de marcher et envoie les ventes plus tard.</div>\n         <div class=\"form\"><button class=\"btn pri\" data-act=\"syncnew\">Relier ce téléphone (téléphone de caisse)</button>\n         <label class=\"f\">Ou entrez le code de liaison du téléphone de caisse<input id=\"barkey\" autocomplete=\"off\" placeholder=\"XXXXX-XXXXX-XXXXX\"></label>\n         <button class=\"btn\" data-act=\"syncjoin\">Rejoindre</button></div>`);\n  }\n  if(canAdmin()) h += `<h3>Sauvegarde</h3><div class=\"row wrap\"><button class=\"btn\" data-act=\"export\">Exporter les ventes (tableur)</button></div>`;\n  if(role!==\"staff\" && hasAdminPin()) h += `<button class=\"btn ghost wide\" style=\"margin-top:16px\" data-act=\"lock\">Verrouiller (mode Serveur)</button>`;\n  return h + `<p class=\"note\">Taux utilisé : 1 € = 655,957 FCFA.</p>`;\n}\n\n/* ---------- fenêtres ---------- */\nlet modalState = null;\nfunction openModal(html, state){ modalState = state||null; const m=$(\"#modal\"); m.innerHTML=`<div class=\"scrim\" data-scrim><div class=\"sheet\" role=\"dialog\" aria-modal=\"true\"><button class=\"close\" data-act=\"close\" aria-label=\"Fermer\">✕</button>${html}</div></div>`; m.hidden=false; }\nfunction closeModal(){ $(\"#modal\").hidden=true; $(\"#modal\").innerHTML=\"\"; modalState=null; }\n\nfunction cartLines(items, editable){\n  return `<div class=\"list\">${items.map((l,i)=>`<div class=\"li\"><div class=\"main\"><b>${esc(l.name)}</b><small class=\"num\">${fcfa(l.price)}</small></div>\n    ${editable?`<div class=\"stepper\"><button data-dec=\"${i}\" aria-label=\"Retirer un\">−</button><b class=\"num\" style=\"min-width:22px;text-align:center\">${l.qty}</b><button data-inc=\"${i}\" aria-label=\"Ajouter un\">+</button></div>`:`<span class=\"num\">× ${l.qty}</span>`}\n    <div class=\"right num\" style=\"min-width:72px\">${fcfa(l.price*l.qty)}</div></div>`).join(\"\")}</div>`;\n}\nfunction showCart(){\n  if(!cart.length){ closeModal(); return; }\n  const tot = cartTotal(cart);\n  openModal(`<h2>Commande</h2>${cartLines(cart,true)}\n  <div class=\"row\" style=\"justify-content:space-between;margin:14px 2px\"><b>Total</b><div class=\"right\"><b class=\"num\" style=\"font-size:20px\">${fcfa(tot)}</b><br><small class=\"num\">${eur(tot)}</small></div></div>\n  <div class=\"form\"><button class=\"btn pri wide\" data-act=\"pay\">Encaisser</button>\n  <button class=\"btn wide\" data-act=\"totable\">Mettre sur une table</button>\n  <button class=\"btn ghost wide\" data-act=\"clearcart\">Vider la commande</button></div>`, {kind:\"cart\"});\n}\nfunction askPrice(p){\n  const opts = p.cat===\"Vins\" ? [5000,6000,7000,8000,10000] : [p.price, p.priceMax];\n  openModal(`<h2>${esc(p.name)}</h2><p>Choisissez le prix :</p>\n  <div class=\"cash\">${opts.map(o=>`<button class=\"btn\" data-pickprice=\"${o}\"><span class=\"num\">${fcfa(o)}</span></button>`).join(\"\")}</div>\n  <div class=\"form\" style=\"margin-top:12px\"><label class=\"f\">Autre prix (FCFA)<input id=\"customprice\" type=\"number\" inputmode=\"numeric\" min=\"0\"></label>\n  <button class=\"btn pri\" data-act=\"customprice\">Ajouter</button></div>`, {kind:\"price\", pid:p.id});\n}\nfunction addToCart(p, price){\n  const l = cart.find(x=>x.pid===p.id && x.price===price);\n  if(l) l.qty++; else cart.push({pid:p.id, name:p.name + (p.priceMax?` (${fcfa(price)})`:\"\"), price, cost:p.cost||0, qty:1});\n  render();\n}\nfunction showPay(items, tabId, partial, client){\n  const tot = cartTotal(items);\n  const sugg = [...new Set([tot, Math.ceil(tot/1000)*1000, Math.ceil(tot/5000)*5000, Math.ceil(tot/10000)*10000])].filter(x=>x>=tot).slice(0,3);\n  openModal(`<h2>Encaisser ${tabId?esc(S.tabs[tabId].name):\"\"}</h2>\n  <div class=\"kpi big\"><div class=\"l\">À payer${partial?\" (part d'un client)\":\"\"}</div><div class=\"v num\" id=\"paytot\">${fcfa(tot)}</div><div class=\"s num\" id=\"payeur\">${eur(tot)}</div></div>\n  ${canCost()?`<h3>Réduction</h3><div class=\"row wrap\">${[5,10,20].map(x=>`<button class=\"btn sm\" data-discpct=\"${x}\">${x} %</button>`).join(\"\")}<button class=\"btn sm ghost\" data-discpct=\"0\">Aucune</button></div>\n  <div class=\"form\" style=\"margin-top:8px\"><div class=\"two\"><input id=\"disc\" type=\"number\" inputmode=\"numeric\" min=\"0\" placeholder=\"Réduction (F)\"><input id=\"discreason\" placeholder=\"Motif (ex. client fidèle)\"></div></div>`:\"\"}\n  <div class=\"form\" style=\"margin-top:12px\"><label class=\"f\">Nom du client (facultatif, imprimé sur le ticket)<input id=\"client\" value=\"${esc(client||\"\")}\" placeholder=\"Ex. Jean, Mme Ndong…\"></label></div>\n  <h3>Mode de paiement</h3>\n  <div class=\"seg\" id=\"paymode\">${[\"Espèces\",\"Mobile Money\",\"Carte\"].map((m,i)=>`<button data-paymode=\"${m}\" aria-pressed=\"${i===0}\">${m}</button>`).join(\"\")}</div>\n  <div id=\"cashbox\"><h3>Montant reçu</h3><div class=\"cash\">${sugg.map(s=>`<button class=\"btn\" data-recv=\"${s}\"><span class=\"num\">${fcfa(s)}</span></button>`).join(\"\")}</div>\n  <div class=\"form\" style=\"margin-top:10px\"><input id=\"recv\" type=\"number\" inputmode=\"numeric\" placeholder=\"Autre montant (FCFA)\" value=\"${tot}\"></div>\n  <p id=\"rendu\" class=\"num\" style=\"font-size:18px;font-weight:700;margin:12px 2px\">Monnaie à rendre : 0 F</p></div>\n  <button class=\"btn pri wide\" data-act=\"confirmpay\">Valider et éditer le ticket</button>`, {kind:\"pay\", items:JSON.parse(JSON.stringify(items)), tabId, partial:!!partial, mode:\"Espèces\", subtotal:tot, discount:0, total:tot});\n}\nfunction setDiscount(v){\n  const st = modalState; st.discount = Math.max(0, Math.min(st.subtotal, Math.round(v||0))); st.total = st.subtotal - st.discount;\n  $(\"#paytot\").textContent = fcfa(st.total) + (st.discount ? `  (−${fcfa(st.discount)})` : \"\"); $(\"#payeur\").textContent = eur(st.total);\n  $(\"#recv\").value = st.total; updRendu();\n}\nfunction updRendu(){\n  const st = modalState; const r = +($(\"#recv\").value||0); const d = r - st.total;\n  $(\"#rendu\").textContent = d>=0 ? `Monnaie à rendre : ${fcfa(d)}` : `Il manque ${fcfa(-d)}`;\n  $(\"#rendu\").style.color = d>=0 ? \"var(--fg)\" : \"var(--bad)\";\n}\nfunction nextTicketNo(day){\n  const n = Object.values(S.tickets).filter(t=>t.day===day).length + 1;\n  return `${day.slice(8,10)}${day.slice(5,7)}-${String(n).padStart(3,\"0\")}`;\n}\nfunction confirmPay(){\n  const st = modalState; const now = new Date(); const day = dayKey(now);\n  const recv = st.mode===\"Espèces\" ? (+($(\"#recv\").value||0)) : st.total;\n  if(st.mode===\"Espèces\" && recv < st.total){ toast(\"Le montant reçu est inférieur au total.\"); return; }\n  const id = uid();\n  const t = {no: nextTicketNo(day), day, ts: now.getTime(), items: st.items.map(l=>({pid:l.pid,name:l.name,price:l.price,cost:l.cost||0,qty:l.qty})),\n    subtotal: st.subtotal, discount: st.discount||0, discountBy: st.discount ? role : null, discountReason: st.discount ? (($(\"#discreason\")||{}).value||\"\").trim() || null : null,\n    total: st.total, pay: st.mode, received: recv, change: recv - st.total, table: st.tabId ? S.tabs[st.tabId].name : null, client: ($(\"#client\").value||\"\").trim() || null};\n  write(\"set\",\"tickets\",id,t);\n  decStock(t.items, -1);\n  if(st.tabId){\n    if(st.partial){\n      const left = (S.tabs[st.tabId].items||[]).map(l=>({...l}));\n      st.items.forEach(a=>{ const l=left.find(x=>x.pid===a.pid&&x.price===a.price); if(l) l.qty-=a.qty; });\n      const rest = left.filter(l=>l.qty>0);\n      if(rest.length) write(\"update\",\"tabs\",st.tabId,{items:rest}); else write(\"delete\",\"tabs\",st.tabId);\n    } else write(\"delete\",\"tabs\",st.tabId);\n  }\n  else cart = [];\n  render(); showTicket(id, true);\n  if(NATIVE){ try{ if(localStorage.getItem(\"caisse-bar.autoprint\")===\"1\") printTicket(t); }catch(e){} }\n}\nfunction decStock(items, sign){\n  const by = {}; items.forEach(l=>{ by[l.pid]=(by[l.pid]||0)+l.qty; });\n  Object.entries(by).forEach(([pid,q])=>{ const p=S.products[pid]; if(p && p.stock!=null) write(\"update\",\"products\",pid,{stock: p.stock + sign*q}); });\n}\nfunction ticketText(t){\n  const s = S.settings.main||{}; const d=new Date(t.ts);\n  const L = [barName().toUpperCase(), `Ticket N° ${t.no}`, `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} ${fmtTime(t.ts)}${t.table?\" - \"+t.table:\"\"}`];\n  if(t.client) L.push(`Client : ${t.client}`);\n  L.push(\"------------------------\");\n  t.items.forEach(l=>L.push(`${l.qty} x ${l.name}  ${fcfa(l.price*l.qty)}`));\n  L.push(\"------------------------\");\n  if(t.discount) L.push(`Sous-total : ${fcfa(t.subtotal)}`, `Réduction : -${fcfa(t.discount)}`);\n  L.push(`TOTAL : ${fcfa(t.total)} (${eur(t.total)})`, `Payé : ${t.pay}${t.pay===\"Espèces\"?` ${fcfa(t.received)} - Rendu ${fcfa(t.change)}`:\"\"}`);\n  if(t.cancelled) L.push(\"*** TICKET ANNULÉ ***\");\n  L.push(s.footer || \"Merci de votre visite !\");\n  return L.join(\"\\n\");\n}\nfunction showTicket(id, fresh){\n  const t = S.tickets[id]; if(!t) return; const s=S.settings.main||{}; const d=new Date(t.ts);\n  openModal(`<div class=\"receipt\">\n    <div class=\"c t\">${esc(barName().toUpperCase())}</div>\n    <div class=\"c\">Ticket N° ${esc(t.no)}</div>\n    <div class=\"c\">${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} · ${fmtTime(t.ts)}${t.table?\" · \"+esc(t.table):\"\"}</div>${t.client?`<div class=\"c\">Client : ${esc(t.client)}</div>`:\"\"}<hr>\n    ${t.items.map(l=>`<div class=\"r\"><span>${l.qty} × ${esc(l.name)}</span><span>${fcfa(l.price*l.qty)}</span></div>`).join(\"\")}<hr>\n    ${t.discount?`<div class=\"r\"><span>Sous-total</span><span>${fcfa(t.subtotal)}</span></div><div class=\"r\"><span>Réduction</span><span>−${fcfa(t.discount)}</span></div>`:\"\"}\n    <div class=\"r tt\"><span>TOTAL</span><span>${fcfa(t.total)}</span></div>\n    <div class=\"r\"><span>soit</span><span>${eur(t.total)}</span></div>\n    <div class=\"r\"><span>Payé (${esc(t.pay)})</span><span>${fcfa(t.received)}</span></div>\n    ${t.pay===\"Espèces\"?`<div class=\"r\"><span>Rendu</span><span>${fcfa(t.change)}</span></div>`:\"\"}\n    ${t.cancelled?`<hr><div class=\"c t\">TICKET ANNULÉ</div>`:\"\"}\n    <hr><div class=\"c\">${esc(s.footer || \"Merci de votre visite !\")}</div>\n  </div>\n  <div class=\"form\">\n    ${NATIVE?`<button class=\"btn ${fresh?\"\":\"pri \"}wide\" data-printticket=\"${id}\">Imprimer le ticket</button>`:\"\"}\n    ${fresh?`<button class=\"btn pri wide\" data-act=\"close\">Nouvelle vente</button>`:\"\"}\n    <div class=\"row\"><button class=\"btn wide\" data-copyticket=\"${id}\">Copier le ticket</button><button class=\"btn wide\" data-saveticket=\"${id}\">Enregistrer</button></div>\n    ${!fresh && !t.cancelled && canCost()?`<input id=\"cancelreason\" placeholder=\"Motif de l'annulation (obligatoire)\"><button class=\"btn danger wide\" data-cancelticket=\"${id}\">Annuler ce ticket</button>`:\"\"}\n  </div>`, {kind:\"ticket\", id});\n}\nfunction showToTable(){\n  const tabs = Object.entries(S.tabs);\n  openModal(`<h2>Mettre sur une table</h2>\n  ${tabs.length?`<h3>Ajouter à une table ouverte</h3><div class=\"list\">${tabs.map(([id,t])=>`<button class=\"li\" data-addtotab=\"${id}\"><div class=\"main\"><b>${esc(t.name)}</b></div><div class=\"right num\">${fcfa(cartTotal(t.items||[]))}</div></button>`).join(\"\")}</div>`:\"\"}\n  <h3>Nouvelle table</h3><div class=\"form\"><input id=\"tabname\" placeholder=\"Ex. Table 4, Terrasse, Jean…\"><button class=\"btn pri\" data-act=\"newtab\">Ouvrir la table</button></div>`, {kind:\"totable\"});\n}\nfunction mergeInto(items, add){ const out = items.map(l=>({...l})); add.forEach(a=>{ const l=out.find(x=>x.pid===a.pid&&x.price===a.price); if(l) l.qty+=a.qty; else out.push({...a}); }); return out; }\nfunction showTab(id){\n  const t = S.tabs[id]; if(!t){ closeModal(); return; } const tot = cartTotal(t.items||[]);\n  openModal(`<h2>${esc(t.name)}</h2><p class=\"num\" style=\"color:var(--muted);margin-top:-6px\">Ouverte à ${fmtTime(t.opened)}</p>\n  ${cartLines(t.items||[], true)}\n  <div class=\"row\" style=\"justify-content:space-between;margin:14px 2px\"><b>Total</b><div class=\"right\"><b class=\"num\" style=\"font-size:20px\">${fcfa(tot)}</b><br><small class=\"num\">${eur(tot)}</small></div></div>\n  <div class=\"form\"><button class=\"btn pri wide\" data-act=\"paytab\">Encaisser toute l'addition</button>\n  <button class=\"btn wide\" data-act=\"splittab\">Faire payer un client séparément</button>\n  <button class=\"btn wide\" data-act=\"addmore\">Ajouter des consommations</button>\n  <button class=\"btn ghost wide\" data-act=\"deltab\">Supprimer cette table</button></div>`, {kind:\"tab\", id});\n}\nfunction showSplit(id, picks){\n  const t = S.tabs[id]; const items = t.items||[]; picks = picks || items.map(()=>0);\n  const tot = items.reduce((s,l,i)=>s+l.price*picks[i],0);\n  openModal(`<h2>Addition séparée</h2><p style=\"color:var(--muted);margin-top:-6px\">${esc(t.name)} · choisissez ce que ce client paie.</p>\n  <div class=\"list\">${items.map((l,i)=>`<div class=\"li\"><div class=\"main\"><b>${esc(l.name)}</b><small class=\"num\">${fcfa(l.price)} · ${l.qty} sur la table</small></div>\n    <div class=\"stepper\"><button data-spdec=\"${i}\" aria-label=\"Retirer un\">−</button><b class=\"num\" style=\"min-width:22px;text-align:center\">${picks[i]}</b><button data-spinc=\"${i}\" aria-label=\"Ajouter un\">+</button></div></div>`).join(\"\")}</div>\n  <div class=\"row\" style=\"justify-content:space-between;margin:14px 2px\"><b>Part du client</b><div class=\"right\"><b class=\"num\" style=\"font-size:20px\">${fcfa(tot)}</b><br><small class=\"num\">${eur(tot)}</small></div></div>\n  <div class=\"form\"><label class=\"f\">Nom du client<input id=\"splitclient\" value=\"${esc((modalState&&modalState.client)||\"\")}\" placeholder=\"Ex. Jean\"></label>\n  <button class=\"btn pri wide\" data-act=\"splitpay\" ${tot?\"\":\"disabled\"}>Encaisser cette part</button></div>`, {kind:\"split\", id, picks});\n}\nfunction showStockEdit(pid){\n  const p = S.products[pid];\n  openModal(`<h2>${esc(p.name)}</h2>\n  <p>En stock : <b class=\"num\">${p.stock==null?\"pas encore compté\":p.stock}</b></p>\n  <h3>Livraison reçue</h3>\n  <div class=\"form\"><div class=\"two\"><label class=\"f\">Quantité reçue<input id=\"rqty\" type=\"number\" inputmode=\"numeric\" min=\"1\"></label>\n  ${canCost()?`<label class=\"f\">Prix d'achat unitaire (F)<input id=\"rcost\" type=\"number\" inputmode=\"numeric\" value=\"${p.cost||\"\"}\"></label>`:\"\"}</div>\n  <button class=\"btn pri\" data-act=\"receive\">Ajouter au stock</button></div>\n  <h3>Inventaire (comptage)</h3>\n  <div class=\"form\"><label class=\"f\">Quantité comptée<input id=\"iqty\" type=\"number\" inputmode=\"numeric\" min=\"0\" value=\"${p.stock??\"\"}\"></label>\n  <label class=\"f\">Alerte « à commander » sous<input id=\"ialert\" type=\"number\" inputmode=\"numeric\" min=\"0\" value=\"${p.alert??6}\"></label>\n  <button class=\"btn\" data-act=\"inventory\">Enregistrer l'inventaire</button></div>`, {kind:\"stock\", pid});\n}\nfunction showProdEdit(pid){\n  const p = pid ? S.products[pid] : {name:\"\",cat:\"Bières\",price:0};\n  openModal(`<h2>${pid?\"Modifier le produit\":\"Nouveau produit\"}</h2>\n  <div class=\"form\"><label class=\"f\">Nom<input id=\"pname\" value=\"${esc(p.name)}\"></label>\n  <label class=\"f\">Catégorie<select id=\"pcat\">${CATS.map(c=>`<option ${c===p.cat?\"selected\":\"\"}>${esc(c)}</option>`).join(\"\")}</select></label>\n  <div class=\"two\"><label class=\"f\">Prix de vente (F)<input id=\"pprice\" type=\"number\" inputmode=\"numeric\" value=\"${p.price||\"\"}\"></label>\n  <label class=\"f\">Prix max si variable<input id=\"pmax\" type=\"number\" inputmode=\"numeric\" value=\"${p.priceMax||\"\"}\"></label></div>\n  <label class=\"f\">Prix d'achat unitaire (F)<input id=\"pcost\" type=\"number\" inputmode=\"numeric\" value=\"${p.cost||\"\"}\" placeholder=\"Pour calculer la marge\"></label>\n  <p class=\"note num\" id=\"peur\">${eur(p.price)}${p.cost?` · marge ${fcfa(p.price-p.cost)} par unité`:\"\"}</p>\n  <button class=\"btn pri\" data-act=\"saveprod\">Enregistrer</button>\n  ${pid?`<button class=\"btn danger\" data-act=\"hideprod\">Retirer de la carte</button>`:\"\"}</div>`, {kind:\"prod\", pid});\n}\nfunction showCostEdit(pid){\n  const p = S.products[pid];\n  openModal(`<h2>${esc(p.name)}</h2><p class=\"num\">Prix de vente : <b>${fcfa(p.price)}</b></p>\n  <div class=\"form\"><label class=\"f\">Prix d'achat unitaire (F)<input id=\"ccost\" type=\"number\" inputmode=\"numeric\" value=\"${p.cost||\"\"}\"></label>\n  <button class=\"btn pri\" data-act=\"savecost\">Enregistrer</button></div>`, {kind:\"cost\", pid});\n}\nfunction showAddCharge(){\n  openModal(`<h2>Nouvelle charge</h2><div class=\"form\">\n  <label class=\"f\">Nature<input id=\"clabel\" placeholder=\"Ex. Électricité, Loyer, Salaire, Glace\"></label>\n  <div class=\"two\"><label class=\"f\">Montant (F)<input id=\"camount\" type=\"number\" inputmode=\"numeric\"></label>\n  <label class=\"f\">Date<input id=\"cday\" type=\"date\" value=\"${dayKey(new Date())}\"></label></div>\n  <button class=\"btn pri\" data-act=\"savecharge\">Enregistrer</button></div>`, {kind:\"charge\"});\n}\n\n/* ---------- actions ---------- */\nasync function copyText(txt){\n  if(NATIVE){ native({type:\"share\", text:txt}); return; }\n  try{ await navigator.clipboard.writeText(txt); toast(\"Ticket copié. Collez-le dans WhatsApp ou SMS.\"); }\n  catch(e){ openModal(`<h2>Ticket</h2><p>Sélectionnez le texte puis copiez-le.</p><textarea style=\"width:100%;height:240px;font-family:var(--f-mono);font-size:13px;background:var(--surface);color:var(--fg);border:1px solid var(--line);border-radius:10px;padding:10px\" readonly>${esc(txt)}</textarea>`); }\n}\nasync function saveFile(filename, data, mime){\n  if(NATIVE){ native({type:\"share\", text:data, filename}); return; }\n  try{\n    const dl = await claude.use(\"downloads\");\n    if(!dl){ toast(\"L'enregistrement de fichier n'est pas disponible ici.\"); return; }\n    await dl.save({filename, data: new Blob([data],{type:mime})});\n  }catch(e){ if(e && e.code!==\"cancelled\" && e.code!==\"declined\") toast(\"Fichier non enregistré.\"); }\n}\nfunction exportCSV(){\n  const rows = [[\"Date\",\"Heure\",\"Ticket\",\"Table\",\"Produit\",\"Quantité\",\"Prix unitaire FCFA\",\"Total FCFA\",\"Total EUR\",\"Prix achat unitaire\",\"Paiement\",\"Annulé\"]];\n  Object.values(S.tickets).sort((a,b)=>a.ts-b.ts).forEach(t=>t.items.forEach(l=>rows.push([t.day,fmtTime(t.ts),t.no,t.table||\"\",l.name,l.qty,l.price,l.price*l.qty,((l.price*l.qty)/RATE).toFixed(2).replace(\".\",\",\"),l.cost||\"\",t.pay,t.cancelled?\"oui\":\"\"])));\n  const csv = \"﻿\" + rows.map(r=>r.map(v=>`\"${String(v).replace(/\"/g,'\"\"')}\"`).join(\";\")).join(\"\\r\\n\");\n  saveFile(`ventes-${dayKey(new Date())}.csv`, csv, \"text/csv\");\n}\nfunction installCarte(){\n  CARTE.forEach(([name,cat,price,priceMax],i)=>{\n    const id = name.normalize(\"NFD\").replace(/[̀-ͯ]/g,\"\").toLowerCase().replace(/[^a-z0-9]+/g,\"-\").replace(/^-|-$/g,\"\");\n    if(S.products[id]) return;\n    const p = {name,cat,price,order:i}; if(priceMax) p.priceMax = priceMax;\n    write(\"set\",\"products\",id,p);\n  });\n  toast(\"Carte installée.\"); render();\n}\nconst num = id => { const v = $(\"#\"+id).value; return v===\"\" ? null : Math.round(+v); };\n\ndocument.addEventListener(\"click\", e=>{\n  const b = e.target.closest(\"button, [data-scrim]\"); if(!b) return;\n  if(b.hasAttribute(\"data-scrim\")){ if(e.target===b) closeModal(); return; }\n  const d = b.dataset;\n  if(d.tab){ tab=d.tab; try{history.replaceState(null,\"\",\"#\"+tab);}catch(_){} closeModal(); render(); $(\"#view\").scrollTop=0; return; }\n  if(d.cat){ cat=d.cat; render(); return; }\n  if(d.add){ const p={id:d.add,...S.products[d.add]}; if(p.priceMax) askPrice(p); else addToCart(p,p.price); return; }\n  if(d.pickprice){ const p={id:modalState.pid,...S.products[modalState.pid]}; closeModal(); addToCart(p,+d.pickprice); return; }\n  if(d.inc!==undefined || d.dec!==undefined){\n    const i = +(d.inc ?? d.dec), delta = d.inc!==undefined ? 1 : -1;\n    if(modalState && modalState.kind===\"tab\"){ const t=S.tabs[modalState.id]; const items=t.items.map(l=>({...l})); items[i].qty+=delta; const out=items.filter(l=>l.qty>0); write(\"update\",\"tabs\",modalState.id,{items:out}); showTab(modalState.id); render(); }\n    else { cart[i].qty+=delta; cart=cart.filter(l=>l.qty>0); render(); showCart(); }\n    return;\n  }\n  if(d.spinc!==undefined || d.spdec!==undefined){\n    const st=modalState, i=+(d.spinc ?? d.spdec), max=S.tabs[st.id].items[i].qty; const c=$(\"#splitclient\").value;\n    st.picks[i]=Math.max(0,Math.min(max, st.picks[i]+(d.spinc!==undefined?1:-1))); modalState.client=c; showSplit(st.id, st.picks); return;\n  }\n  if(d.shiftname!==undefined){ startShift(d.shiftname); return; }\n  if(d.shiftend){ const x=S.shifts[d.shiftend]; if(!x) return;\n    if(b.dataset.armed){ const now=Date.now(); write(\"update\",\"shifts\",d.shiftend,{end:now}); toast(`Fin de service pour ${x.name} : ${fmtDur(now-x.start)}.`); render(); }\n    else { b.dataset.armed=\"1\"; b.textContent=\"Confirmer la fin\"; setTimeout(()=>{ if(b.isConnected){ delete b.dataset.armed; b.textContent=\"Fin de service\"; } }, 5000); }\n    return; }\n  if(d.shiftedit){ if(canCost()) showShiftEdit(d.shiftedit); return; }\n  if(d.locopen){ showLoc(d.locopen); return; }\n  if(d.appedit){ if(canAdmin()) showAppartEdit(d.appedit); return; }\n  if(d.tabopen){ showTab(d.tabopen); return; }\n  if(d.addtotab){ write(\"update\",\"tabs\",d.addtotab,{items: mergeInto(S.tabs[d.addtotab].items||[], cart)}); toast(`Ajouté à ${S.tabs[d.addtotab].name}.`); cart=[]; closeModal(); render(); return; }\n  if(d.stk){ showStockEdit(d.stk); return; }\n  if(d.edit){ if(canAdmin()) showProdEdit(d.edit); return; }\n  if(d.costedit){ if(canCost()) showCostEdit(d.costedit); return; }\n  if(d.ticket){ showTicket(d.ticket,false); return; }\n  if(d.copyticket){ copyText(ticketText(S.tickets[d.copyticket])); return; }\n  if(d.printticket){ printTicket(S.tickets[d.printticket]); return; }\n  if(d.printer){ setPrinter({address:d.printer, name:d.pname}); toast(`Imprimante : ${d.pname||d.printer}`); closeModal(); render(); return; }\n  if(d.saveticket){ const t=S.tickets[d.saveticket]; saveFile(`ticket-${t.no}.txt`, ticketText(t), \"text/plain\"); return; }\n  if(d.cancelticket){ if(!canCost()) return;\n    const reason = ($(\"#cancelreason\").value||\"\").trim(); if(!reason){ toast(\"Indiquez le motif de l'annulation.\"); return; }\n    if(b.dataset.armed){ const t=S.tickets[d.cancelticket]; write(\"update\",\"tickets\",d.cancelticket,{cancelled:true, cancelledAt:Date.now(), cancelledBy:role, cancelReason:reason}); decStock(t.items, +1); toast(\"Ticket annulé, stock remis.\"); closeModal(); render(); }\n    else { b.dataset.armed=\"1\"; b.textContent=\"Touchez encore pour confirmer l'annulation\"; }\n    return;\n  }\n  if(d.delcharge){ if(!canAdmin()) return; write(\"delete\",\"charges\",d.delcharge); render(); return; }\n  if(d.mode){ period.mode=d.mode; render(); return; }\n  if(d.shift){ const s=+d.shift, r=new Date(period.ref);\n    if(period.mode===\"jour\") r.setDate(r.getDate()+s); else if(period.mode===\"semaine\") r.setDate(r.getDate()+7*s); else { r.setDate(1); r.setMonth(r.getMonth()+s); }\n    period.ref=r; render(); return; }\n  if(d.discpct!==undefined){ const v = Math.round(modalState.subtotal*(+d.discpct)/100); $(\"#disc\").value = v||\"\"; setDiscount(v); return; }\n  if(d.paymode){ modalState.mode=d.paymode; document.querySelectorAll(\"[data-paymode]\").forEach(x=>x.setAttribute(\"aria-pressed\",x===b)); $(\"#cashbox\").hidden = d.paymode!==\"Espèces\"; return; }\n  if(d.recv){ $(\"#recv\").value=d.recv; updRendu(); return; }\n  switch(d.act){\n    case \"close\": closeModal(); break;\n    case \"role\": if(role===\"staff\") showPin(); else if(hasAdminPin()) lock(); else { tab=\"plus\"; render(); toast(\"Créez d'abord votre code administrateur.\"); } break;\n    case \"lock\": lock(); break;\n    case \"unlock\": { const h=hashPin($(\"#pin\").value.trim()); const s=pins();\n      if(s.adminPin && h===s.adminPin) role=\"admin\"; else if(s.gestPin && h===s.gestPin) role=\"gest\"; else { toast(\"Code incorrect.\"); $(\"#pin\").value=\"\"; return; }\n      unlocked = true; closeModal(); bumpIdle(); render(); toast(`Bienvenue, ${ROLE_NAMES[role]}.`); break; }\n    case \"setadmin\": { if(!canAdmin()) return; const v=$(\"#newadmin\").value.trim(); if(!/^\\d{4,}$/.test(v)){ toast(\"Le code doit avoir au moins 4 chiffres.\"); return; }\n      if(pins().gestPin===hashPin(v)){ toast(\"Choisissez un code différent du code gérante.\"); return; }\n      unlocked = true; write(\"set\",\"settings\",\"main\",{...pins(), adminPin:hashPin(v)}); toast(\"Code administrateur enregistré. Notez-le bien.\"); render(); break; }\n    case \"setgest\": { if(!canAdmin()) return; const v=$(\"#newgest\").value.trim(); if(!/^\\d{4,}$/.test(v)){ toast(\"Le code doit avoir au moins 4 chiffres.\"); return; }\n      if(!hasAdminPin()){ toast(\"Créez d'abord votre code administrateur.\"); return; }\n      if(pins().adminPin===hashPin(v)){ toast(\"Choisissez un code différent du vôtre.\"); return; }\n      write(\"set\",\"settings\",\"main\",{...pins(), gestPin:hashPin(v)}); toast(\"Code gérante enregistré.\"); render(); break; }\n    case \"delgest\": { if(!canAdmin()) return; const n={...pins()}; delete n.gestPin; write(\"set\",\"settings\",\"main\",n); toast(\"Code gérante supprimé.\"); render(); break; }\n    case \"savecost\": { if(!canCost()) return; const c=num(\"ccost\"); write(\"update\",\"products\",modalState.pid,{cost:c||null}); toast(\"Prix d'achat enregistré.\"); closeModal(); render(); break; }\n    case \"install\": installCarte(); break;\n    case \"cart\": showCart(); break;\n    case \"pay\": showPay(cart,null); break;\n    case \"confirmpay\": confirmPay(); break;\n    case \"clearcart\": cart=[]; closeModal(); render(); break;\n    case \"totable\": showToTable(); break;\n    case \"newtab\": { const name=$(\"#tabname\").value.trim(); if(!name){ toast(\"Donnez un nom à la table.\"); return; }\n      write(\"set\",\"tabs\",uid(),{name, opened:Date.now(), items:cart}); cart=[]; closeModal(); toast(`${name} ouverte.`); render(); break; }\n    case \"splittab\": showSplit(modalState.id); break;\n    case \"splitpay\": { const st=modalState; const items=S.tabs[st.id].items.map((l,i)=>({...l,qty:st.picks[i]})).filter(l=>l.qty>0);\n      showPay(items, st.id, true, $(\"#splitclient\").value.trim()); break; }\n    case \"paytab\": showPay(S.tabs[modalState.id].items||[], modalState.id); break;\n    case \"addmore\": { closeModal(); tab=\"caisse\"; render(); toast(`Choisissez les consommations, puis « Voir » et « Mettre sur une table ».`); break; }\n    case \"deltab\": if(b.dataset.armed){ write(\"delete\",\"tabs\",modalState.id); closeModal(); render(); } else { b.dataset.armed=\"1\"; b.textContent=\"Touchez encore pour supprimer\"; } break;\n    case \"customprice\": { const v=num(\"customprice\"); if(!v){ toast(\"Entrez un prix.\"); return; } const p={id:modalState.pid,...S.products[modalState.pid]}; closeModal(); addToCart(p,v); break; }\n    case \"receive\": { const q=num(\"rqty\"), c=canCost()?num(\"rcost\"):null; if(!q){ toast(\"Entrez la quantité reçue.\"); return; } const p=S.products[modalState.pid];\n      const upd={stock:(p.stock||0)+q}; if(c) upd.cost=c; write(\"update\",\"products\",modalState.pid,upd);\n      write(\"set\",\"moves\",uid(),{pid:modalState.pid,name:p.name,type:\"recv\",qty:q,cost:c||null,ts:Date.now(),day:dayKey(new Date())});\n      toast(`+${q} ${p.name}`); closeModal(); render(); break; }\n    case \"inventory\": { const q=num(\"iqty\"), a=num(\"ialert\"); if(q==null){ toast(\"Entrez la quantité comptée.\"); return; } const p=S.products[modalState.pid];\n      write(\"update\",\"products\",modalState.pid,{stock:q, alert:a??6});\n      write(\"set\",\"moves\",uid(),{pid:modalState.pid,name:p.name,type:\"inv\",qty:q,ts:Date.now(),day:dayKey(new Date())});\n      toast(\"Inventaire enregistré.\"); closeModal(); render(); break; }\n    case \"saveprod\": { if(!canAdmin()) return; const name=$(\"#pname\").value.trim(), price=num(\"pprice\"); if(!name||!price){ toast(\"Le nom et le prix sont obligatoires.\"); return; }\n      const data={name,cat:$(\"#pcat\").value,price}; const mx=num(\"pmax\"), c=num(\"pcost\"); data.priceMax = mx && mx>price ? mx : null; data.cost = c||null;\n      if(modalState.pid) write(\"update\",\"products\",modalState.pid,data); else write(\"set\",\"products\",uid(),{...data,order:999});\n      toast(\"Produit enregistré.\"); closeModal(); render(); break; }\n    case \"hideprod\": if(!canAdmin()) return; write(\"update\",\"products\",modalState.pid,{hidden:true}); closeModal(); render(); break;\n    case \"savebar\": if(!canAdmin()) return; write(\"set\",\"settings\",\"main\",{...(S.settings.main||{}), barName:$(\"#barname\").value.trim(), footer:$(\"#footer\").value.trim()}); toast(\"Enregistré.\"); render(); break;\n    case \"addcharge\": if(!canAdmin()) return; showAddCharge(); break;\n    case \"savecharge\": { if(!canAdmin()) return; const label=$(\"#clabel\").value.trim(), amount=num(\"camount\"), day=$(\"#cday\").value; if(!label||!amount||!day){ toast(\"Remplissez la nature, le montant et la date.\"); return; }\n      write(\"set\",\"charges\",uid(),{label,amount,day}); toast(\"Charge ajoutée.\"); closeModal(); render(); break; }\n    case \"newprod\": if(!canAdmin()) return; showProdEdit(null); break;\n    case \"export\": if(!canAdmin()) return; exportCSV(); break;\n    case \"syncnew\": { if(!canAdmin()) return; lsSet(SYNC_LS, {bar:newBarKey()}); lsSet(SYNCLAST_LS, \"1970-01-01T00:00:00Z\"); syncStartAll(); toast(\"Téléphone relié.\"); render(); break; }\n    case \"syncjoin\": { if(!canAdmin()) return; const k=($(\"#barkey\").value||\"\").trim().toUpperCase().replace(/[^A-Z0-9]/g,\"\").replace(/(.{5})(?=.)/g,\"$1-\"); if(k.length<17){ toast(\"Le code de liaison a 15 caractères.\"); return; }\n      lsSet(SYNC_LS, {bar:k}); lsSet(SYNCLAST_LS, \"1970-01-01T00:00:00Z\"); syncQ=[]; lsSet(SYNCQ_LS, syncQ); toast(\"Récupération des ventes…\");\n      syncPull().then(()=>{ toast(syncErr ? \"Connexion impossible. Vérifiez internet et le code.\" : \"Téléphone relié. Les ventes s'affichent.\"); render(); }); break; }\n    case \"syncoff\": { if(!canAdmin()) return; if(b.dataset.armed){ lsSet(SYNC_LS, null); toast(\"Téléphone délié.\"); render(); } else { b.dataset.armed=\"1\"; b.textContent=\"Touchez encore pour délier\"; } break; }\n    case \"newappart\": if(!canAdmin()) return; showAppartEdit(null); break;\n    case \"saveappart\": { if(!canAdmin()) return; const name=$(\"#aname\").value.trim(), price=num(\"aprice\"); if(!name||!price){ toast(\"Le nom et le prix de la nuit sont obligatoires.\"); return; }\n      const data={name, dayPrice:price, weekDisc:Math.min(100,num(\"aweek\")||0), monthDisc:Math.min(100,num(\"amonth\")||0)};\n      if(modalState.id) write(\"update\",\"apparts\",modalState.id,data); else write(\"set\",\"apparts\",uid(),data);\n      toast(\"Logement enregistré.\"); closeModal(); render(); break; }\n    case \"hideappart\": if(!canAdmin()) return; write(\"update\",\"apparts\",modalState.id,{hidden:true}); closeModal(); render(); break;\n    case \"newloc\": if(!canCost()) return; showLocEdit(null); break;\n    case \"saveloc\": { if(!canCost()) return; locPreview(); const c=modalState.calc; if(!c){ toast(\"Vérifiez le logement et les dates.\"); return; }\n      const data={appart:$(\"#lapp\").value, start:$(\"#lstart\").value, end:$(\"#lend\").value, client:$(\"#lclient\").value.trim(), phone:$(\"#lphone\").value.trim(),\n        nights:c.nights, dayPrice:S.apparts[$(\"#lapp\").value].dayPrice, base:c.base, pct:c.pct, auto:c.auto, extra:c.extra, total:c.total,\n        paid:Math.max(0,num(\"lpaid\")||0), pay:$(\"#lpay\").value, by:role, day:$(\"#lstart\").value};\n      if(modalState.id) write(\"update\",\"locations\",modalState.id,data); else write(\"set\",\"locations\",uid(),{...data, created:Date.now()});\n      toast(\"Location enregistrée.\"); closeModal(); render(); break; }\n    case \"locedit\": { const id=modalState.id; showLocEdit(id); break; }\n    case \"locpaid\": { const l=S.locations[modalState.id]; write(\"update\",\"locations\",modalState.id,{paid:l.total}); toast(\"Location payée.\"); showLoc(modalState.id); render(); break; }\n    case \"locprint\": printTicket(locAsTicket(S.locations[modalState.id])); break;\n    case \"loccancel\": { if(!canCost()) return; if(b.dataset.armed){ write(\"update\",\"locations\",modalState.id,{cancelled:true, cancelledAt:Date.now(), cancelledBy:role}); toast(\"Location annulée.\"); closeModal(); render(); } else { b.dataset.armed=\"1\"; b.textContent=\"Touchez encore pour annuler la location\"; } break; }\n    case \"addlcharge\": if(!canCost()) return; showAddLCharge(); break;\n    case \"savelcharge\": { if(!canCost()) return; const label=$(\"#lclabel\").value.trim(), amount=num(\"lcamount\"), day=$(\"#lcday\").value; if(!label||!amount||!day){ toast(\"Remplissez la nature, le montant et la date.\"); return; }\n      write(\"set\",\"charges\",uid(),{label,amount,day,scope:\"appart\",appart:$(\"#lcapp\").value||null}); toast(\"Charge ajoutée.\"); closeModal(); render(); break; }\n    case \"shiftstart\": showShiftStart(false); break;\n    case \"shiftgo\": startShift($(\"#shiftname\").value); break;\n    case \"saveshift\": { if(!canCost()) return; const name=$(\"#sename\").value.trim(), day=$(\"#seday\").value, a=$(\"#sestart\").value, z=$(\"#seend\").value;\n      if(!name||!day||!a){ toast(\"Le prénom, la date et le début sont obligatoires.\"); return; }\n      const [y,mo,dd]=day.split(\"-\").map(Number), at=(hm,plus)=>{ const [hh,mm]=hm.split(\":\").map(Number); return new Date(y,mo-1,dd+(plus||0),hh,mm).getTime(); };\n      const start=at(a); let end=z?at(z):null; if(end!=null && end<=start) end=at(z,1);\n      write(\"update\",\"shifts\",modalState.id,{name,start,end,day,editedBy:role,editedAt:Date.now()}); toast(\"Service corrigé.\"); closeModal(); render(); break; }\n    case \"delshift\": { if(!canCost()) return; if(b.dataset.armed){ write(\"update\",\"shifts\",modalState.id,{deleted:true,editedBy:role,editedAt:Date.now()}); toast(\"Service supprimé.\"); closeModal(); render(); } else { b.dataset.armed=\"1\"; b.textContent=\"Touchez encore pour supprimer\"; } break; }\n    case \"pickprinter\": native({type:\"listPrinters\"}); break;\n    case \"testprint\": printTicket({no:\"TEST\", ts:Date.now(), items:[{qty:1,name:\"Test d'impression éàç\",price:700}], total:700, pay:\"Espèces\", received:1000, change:300}); break;\n  }\n});\ndocument.addEventListener(\"change\", e=>{ if([\"lapp\",\"lstart\",\"lend\"].includes(e.target.id)) locPreview(); if(e.target.id===\"autoprint\"){ try{ localStorage.setItem(\"caisse-bar.autoprint\", e.target.checked?\"1\":\"0\"); }catch(_){} } });\ndocument.addEventListener(\"input\", e=>{\n  if(e.target.id===\"recv\") updRendu();\n  if([\"lapp\",\"lstart\",\"lend\",\"lextra\"].includes(e.target.id)) locPreview();\n  if(e.target.id===\"disc\") setDiscount(+e.target.value);\n  if(e.target.id===\"pprice\"||e.target.id===\"pcost\"){ const p=+($(\"#pprice\").value||0), c=+($(\"#pcost\").value||0); $(\"#peur\").textContent = eur(p) + (c?` · marge ${fcfa(p-c)} par unité`:\"\"); }\n});\nwindow.addEventListener(\"online\", flush);\ndocument.addEventListener(\"visibilitychange\", ()=>{ if(document.hidden) lock(); });\n[\"click\",\"input\"].forEach(ev=>document.addEventListener(ev, ()=>{ if(role!==\"staff\") bumpIdle(); }, true));\ndocument.addEventListener(\"visibilitychange\", ()=>{ if(!document.hidden) flush(); });\nsetInterval(()=>{ if(queue.length) flush(); }, 20000);\n\n/* ---------- démarrage ---------- */\nloadLocal(); render(); setSync();\nfunction askShiftOnOpen(){ // téléphone de caisse : proposer le début de service si personne n'est en service\n  let dev = false; try{ dev = localStorage.getItem(SHIFTDEV_LS)===\"1\"; }catch(e){}\n  if(dev && !openShifts().length && role===\"staff\" && $(\"#modal\").hidden) showShiftStart(true);\n}\nsetTimeout(askShiftOnOpen, 1500);\ndocument.addEventListener(\"visibilitychange\", ()=>{ if(!document.hidden) setTimeout(askShiftOnOpen, 800); });\n(async()=>{\n  for(let i=0;i<30 && !window.claude;i++) await new Promise(r=>setTimeout(r,100));\n  try{ db = window.claude ? await window.claude.use(\"db\") : null; }catch(e){ db = null; }\n  if(db){ subscribe(); flush(); } else { setSync(); if(syncCfg()){ syncFlush(); syncPull(); } }\n  setInterval(()=>{ if(!db && syncCfg()){ syncFlush(); syncPull(); } }, 20000);\n  document.addEventListener(\"visibilitychange\", ()=>{ if(!document.hidden && !db && syncCfg()) syncPull(); });\n})();\n</script>\n</body></html>";
